INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('EVENT_LOGS_TASKSCHEDULER', 'Event Logs - Task Scheduler', 'Windows', 'Medium', NULL, 880, NULL, NULL, NULL, 'SELECT System.TimeCreated.SystemTime AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value AS EventID, System.EventRecordID AS EventRecordID, System.Security.UserID AS UserID, Message FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-TaskScheduler%4Operational.evtx'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('EVENT_LOGS_SECURITY', 'Event Logs - Security', 'Windows', 'High', NULL, 875, NULL, NULL, NULL, 'SELECT System.TimeCreated.SystemTime AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value AS EventID, System.EventRecordID AS EventRecordID, System.Security.UserID AS UserID, Message FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('EVENT_LOGS_SYSTEM', 'Event Logs - System', 'Windows', 'High', NULL, 876, NULL, NULL, NULL, 'SELECT System.TimeCreated.SystemTime AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value AS EventID, System.EventRecordID AS EventRecordID, System.Security.UserID AS UserID, Message FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/System.evtx'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('AMCACHE', 'Amcache', NULL, NULL, NULL, 895, NULL, NULL, NULL, 'SELECT Timestamp, Name, PackageFullName, Version, Publisher, SourceApp, Type, SHA1, ManifestPath, InstallDate, Language, UninstallString FROM Artifact.Windows.Forensics.Amcache()', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1562.006', 'Impair Defenses: Indicator Blocking', NULL, 'High', NULL, 349, 'Network configuration files and registry proxy settings.', 'Detect modifications to the ''hosts'' file that redirect security vendor update domains (e.g., ''av-updates.com'') to 127.0.0.1.', 'Analyze the ''hosts'' file and browser proxy settings for entries that isolate the host from security cloud intelligence.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1562.008', 'Impair Defenses: Disable Cloud Logs', NULL, 'Critical', NULL, 350, 'Cloud service provider configuration audit and global audit logs.', 'Monitor for ''StopLogging'', ''DeleteTrail'', or ''UpdateS3BucketPolicy'' events that disable or restrict audit log collection.', 'Analyze cloud provider logs for gaps in recording or the removal of log-destination buckets/resource groups.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1562.009', 'Impair Defenses: Safe Mode Boot', NULL, 'High', NULL, 351, 'SYSTEM registry hive and BCD configuration.', 'Detect ''bcdedit /set {default} safeboot minimal'' which is used to reboot into a state where most security software is disabled.', 'Check ''Bootstat.dat'' and registry keys for evidence of recent Safe Mode boots used to perform manual cleanup/encryption.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1621', 'Multi-Factor Authentication Request Generation', NULL, 'Critical', NULL, 474, 'Collect Azure Sign-in Logs focusing on MFA-related events (ResultType 50074, 50076). Gather AWS CloudTrail logs for AssumeRole and ConsoleLogin events with repeated MFA failures. Obtain Windows Security Event Logs (Event ID 4625) for failed authentication attempts. Collect Linux auditd AUTH logs for pam_unix and pam_google_authenticator events. Retrieve SaaS provider logs from Okta (MFAChallengeIssued events), Duo, or Microsoft Authenticator. Gather macOS Unified Logs for authd MFA token requests. Collect network security monitoring data for connection patterns and geolocation analysis. Obtain push notification service logs where available.', '1. Query identity provider logs for excessive MFA requests: Check Azure Sign-in Logs for events with ResultType 50074 (MFA required) or 50076 (MFA challenge failed) occurring in rapid succession for the same user. 2. Examine Windows Security logs for Event ID 4625 (failed logon) followed by multiple authentication events: Look for patterns where failed logons precede MFA challenge generation. 3. Monitor active MFA service APIs: Query Duo, Okta, or Microsoft Authenticator admin consoles for push notification frequency and user response patterns. 4. Check network connections for unusual geographic origins: Correlate MFA requests with source IP addresses and geolocations that don''t match normal user behavior. 5. Review current active sessions: Identify if successful authentication occurred immediately after multiple denied/timed-out MFA requests indicating potential fatigue acceptance.', '1. Parse Azure Sign-in Logs or exported identity provider logs for MFA challenge patterns: Extract events showing repeated MFA requests (50074, 50076) within short time windows for individual users. 2. Analyze Windows Security Event Logs (Security.evtx) for authentication sequences: Search for Event ID 4625 patterns followed by MFA-related events, focusing on source IP correlation. 3. Extract browser artifacts and cached authentication tokens: Examine browser history, cookies, and stored credentials that may indicate successful session establishment after MFA bypass. 4. Review application-specific logs: Parse logs from enterprise applications that integrate with MFA providers to identify successful access after suspected fatigue attacks. 5. Correlate timestamp analysis across log sources: Map failed authentications, MFA requests, and successful logons to establish attack timelines and success rates.', 'SELECT EventTime, Computer, EventData.TargetUserName as Username, EventData.IpAddress as SourceIP, EventData.LogonType, EventData.Status, EventData.SubStatus FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE System.EventID.Value = 4625 AND EventData.Status = ''0xc000006d'' ORDER BY Username', 'name: Custom.T1621.MFAFatigueDetection
description: Detect Multi-Factor Authentication Request Generation (MFA Fatigue) attacks across multiple log sources
imports:
  - Linux.Events.Journal
  - MacOS.System.UnifiedLogs
  - Windows.EventLogs.Evtx
sources:
  - name: WindowsFailedLogins
    query: |
      SELECT EventTime, Computer, EventData.TargetUserName as Username, EventData.IpAddress as SourceIP, EventData.LogonType, EventData.Status
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE System.EventID = 4625 AND EventTime > now() - 86400
      ORDER BY Username, EventTime
  - name: LinuxAuthAttempts
    query: |
      SELECT timestamp, hostname, exe, msg
      FROM source(artifact=''Linux.Events.Journal'')
      WHERE msg =~ ''pam_unix|pam_google_authenticator'' AND timestamp > now() - 86400
      ORDER BY timestamp
  - name: MacOSAuthRequests
    query: |
      SELECT timestamp, process, message
      FROM source(artifact=''MacOS.System.UnifiedLogs'')
      WHERE process = ''authd'' AND message =~ ''MFA|token'' AND timestamp > now() - 86400
      ORDER BY timestamp', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1021.001', 'Remote Services: Remote Desktop Protocol', NULL, 'High', NULL, 25, 'Collect Windows Security Event Log (Event IDs 4624, 4648, 4778, 4779), RemoteConnectionManager operational logs, Sysmon logs (Event IDs 1, 3, 22 for process creation and network connections), RDP bitmap cache directories (%USERPROFILE%\AppData\Local\Microsoft\Terminal Server Client\Cache\), Terminal Services registry keys (HKLM\SYSTEM\CurrentControlSet\Control\Terminal Server), user registry hives for RDP connection history (NTUSER.DAT\Software\Microsoft\Terminal Server Client), and TerminalServices-RemoteConnectionManager event logs for connection source tracking.', '1. Check active RDP sessions with ''qwinsta'' to see current RDP connections and session states. 2. Examine running processes with ''tasklist /v'' to identify ''rdpclip.exe'' and ''winlogon.exe'' processes associated with RDP sessions. 3. Query network connections with ''netstat -ano | findstr :3389'' to identify active RDP listeners and established connections on port 3389. 4. Check recent logon events with ''wevtutil qe Security /f:text /q:"*[System[(EventID=4624)] and EventData[Data[@Name=''LogonType'']=''10'']]" /c:20'' for RDP logon type 10 events. 5. Review RDP configuration in registry at ''HKLM\SYSTEM\CurrentControlSet\Control\Terminal Server'' to confirm RDP is enabled (fDenyTSConnections=0).', '1. Parse Security.evtx for Event ID 4624 with LogonType 10 (RDP) and Event ID 4778/4779 (session connect/disconnect) to establish RDP usage timeline. 2. Examine RemoteConnectionManager operational logs for Event ID 1149 to identify source IP addresses of RDP connections. 3. Analyze RDP bitmap cache files in ''%USERPROFILE%\AppData\Local\Microsoft\Terminal Server Client\Cache\'' to reconstruct screen content viewed during sessions. 4. Review MFT entries for recent access to RDP-related executables like mstsc.exe and rdpclip.exe. 5. Check registry artifacts at ''NTUSER.DAT\Software\Microsoft\Terminal Server Client\Servers'' for RDP connection history and recently accessed servers.', 'SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName, EventData.WorkstationName FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE System.EventID.Value = 4624 AND EventData.LogonType = ''10'' AND EventData.IpAddress != ''-'' AND EventData.IpAddress != NULL AND NOT EventData.TargetUserName =~ ''(?i)(SYSTEM|\$)''', 'name: Windows.RDP.Investigation
description: Collect RDP-related artifacts including logon events, connection manager logs, and bitmap cache
sources:
  - name: RDP_Logon_Events
    query: |
      SELECT EventTime, Computer, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName, EventData.WorkstationName, EventData.ProcessName
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE Channel = ''Security'' AND (EventID = 4624 AND EventData.LogonType = 10) OR EventID = 4778 OR EventID = 4779
  - name: RDP_Connection_Manager
    query: |
      SELECT EventTime, Computer, EventData
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE Channel = ''Microsoft-Windows-TerminalServices-RemoteConnectionManager/Operational'' AND EventID = 1149
  - name: RDP_Bitmap_Cache
    query: |
      SELECT FullPath, Mtime, Atime, Size
      FROM glob(globs=[''C:/Users/*/AppData/Local/Microsoft/Terminal Server Client/Cache/*''])
      WHERE Size > 0', '2026-06-10 12:41:37.243319');
