INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('REGISTRY_SYSTEM', 'Registry - SYSTEM', 'Windows', 'High', NULL, 884, NULL, NULL, NULL, 'SELECT Key.FileInfo.FullPath AS KeyPath, Key.FileInfo.ModTime AS KeyModTime, Key.Values AS Values FROM read_reg_key(root=''HKEY_LOCAL_MACHINE'', globs=''SYSTEM/**'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('REGISTRY_SECURITY', 'Registry - SECURITY', 'Windows', 'High', NULL, 886, NULL, NULL, NULL, 'SELECT Key.FileInfo.FullPath AS KeyPath, Key.FileInfo.ModTime AS KeyModTime, Key.Values AS Values FROM read_reg_key(root=''HKEY_LOCAL_MACHINE'', globs=''SECURITY/**'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('REGISTRY_USRCLASS', 'Registry - UsrClass', 'Windows', 'Medium', NULL, 887, NULL, NULL, NULL, 'SELECT Key.FileInfo.FullPath AS KeyPath, Key.FileInfo.ModTime AS KeyModTime, Key.Values AS Values FROM read_reg_key(root=''HKEY_USERS'', globs=''*/Software/Classes/Local Settings/Software/Microsoft/Windows/Shell/BagMRU/**'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1059.004', 'Command and Scripting Interpreter: Unix Shell', NULL, 'Critical', NULL, 94, 'Collect auditd SYSCALL logs focusing on execve events for shell interpreters (/var/log/audit/audit.log). Gather authentication logs (auth.log, secure.log) for shell login tracking. On Linux, collect osquery socket_events and process_events data. For macOS, obtain unified logs with shell execution predicates and launchd process events. On ESXi, collect vmkernel logs for DCUI and BusyBox activity plus authentication logs for shell access. Gather all shell history files (.bash_history, .zsh_history, .sh_history) from user directories. For network devices, collect syslog CLI command audit trails and remote access flow data.', '1. Monitor active shell processes using ''ps aux | grep -E "(bash|sh|zsh|ash)"'' and check for unusual parent processes or command arguments. 2. Examine current shell history with ''history'' command and check for suspicious patterns like base64 decoding, curl pipes, or reverse shell syntax. 3. Review active network connections from shell processes using ''lsof -i -a -p <shell_pid>'' to identify potential C2 channels. 4. Check auditd logs in real-time with ''ausearch -c bash -c sh -c zsh --start recent'' for execve syscalls from shells. 5. On macOS, use ''log stream --predicate "eventMessage CONTAINS "exec""'' to monitor shell execution from non-Terminal applications. 6. For ESXi systems, check DCUI logs and vmkernel logs for unexpected BusyBox or ash shell activity.', '1. Extract and analyze shell history files (.bash_history, .zsh_history, .sh_history) from all user directories, including deleted entries and timestamped history formats. 2. Parse auditd logs (/var/log/audit/audit.log) for execve syscalls involving shell interpreters, focusing on unusual parent processes or command chains. 3. Examine system logs (/var/log/auth.log, /var/log/secure) for shell login events and privilege escalation activities. 4. On macOS, parse unified logs and ASL logs for shell execution outside Terminal.app context, particularly from LaunchAgents/LaunchDaemons. 5. Check for script artifacts in common locations (/tmp, /var/tmp, /Users/Shared on macOS) and analyze their content for malicious payloads. 6. Review cron jobs and scheduled tasks that may invoke shells for persistence mechanisms.', 'SELECT timestamp, Exe, CommandLine, Pid, Ppid, Username 
FROM parse_journald(filename=''/var/log/journal'') 
WHERE MESSAGE =~ ''type=EXECVE'' 
  AND Exe =~ ''/bin/bash''', '', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1070.002', 'Indicator Removal on Host: Clear Windows Event Logs', NULL, 'Critical', NULL, 108, 'Immediate capture of all .evtx files; search for gaps in the chronological sequence of events.', '1. Monitor for ''wevtutil cl'' or ''Clear-EventLog'' commands.
2. Watch for the ''EventLog'' service entering a stopped state unexpectedly.', '1. Search for ''System'' Event ID 104 (The System log file was cleared) or ''Security'' Event ID 1102.
2. Correlate the time the log was cleared with the ''LastRunTime'' of administrative tools in Prefetch.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1019', 'System Firmware', 'Windows/Linux', 'Medium', 'Review system artifacts.', 535, 'Standard Triage', 'Verify BIOS/UEFI version hash.', 'Perform SPI flash dump/analysis.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1496.001', 'Resource Hijacking: Impact for Resource Exhaustion', NULL, 'Medium', NULL, 260, 'Collect Sysmon logs (Microsoft-Windows-Sysmon/Operational) focusing on EventCode=1 (process creation), EventCode=3 (network connections), and EventCode=22 (DNS queries). Gather Windows Security logs (Security.evtx) for EventCode=4698 (scheduled task creation). Obtain NSM flow data for outbound connections to mining pool ports (3333, 4444, 5555). For Linux environments, collect auditd logs with execve syscall data and cron execution logs. For containers, gather containerd events focusing on container create events and Docker/Kubernetes API logs. For cloud environments, collect AWS CloudTrail RunInstances events and CloudWatch CPU utilization metrics. Include performance monitor logs showing sustained high CPU usage and WMI event logs for potential WMI-based process launches.', '1. Check active processes for high CPU usage: Get-Process | Sort-Object CPU -Descending | Select-Object -First 10 Name,CPU,Path,Id and identify unfamiliar executables with sustained high resource consumption. 2. Examine network connections from suspicious processes: netstat -ano | findstr <PID> and look for connections to mining pool ports (3333, 4444, 5555, 8333, 14433). 3. Query Sysmon Event ID 1 for recent process creation: Get-WinEvent -FilterHashtable @{LogName=''Microsoft-Windows-Sysmon/Operational''; ID=1} | Where-Object {$_.TimeCreated -gt (Get-Date).AddHours(-24)} and correlate with high-CPU processes. 4. Check scheduled tasks for persistence: Get-ScheduledTask | Where-Object {$_.State -eq ''Running'' -or $_.State -eq ''Ready''} | Select-Object TaskName,TaskPath,Actions and examine for cryptocurrency miner binaries. 5. Review Sysmon Event ID 3 network connections: Get-WinEvent -FilterHashtable @{LogName=''Microsoft-Windows-Sysmon/Operational''; ID=3} | Where-Object {$_.Message -match ''3333|4444|5555|stratum''} for mining pool communications. 6. For containers, check running containers: docker ps -a and kubectl get pods --all-namespaces to identify unauthorized or suspicious container deployments with high resource usage.', '1. Parse Windows Event Logs for Sysmon EventID 1 (process creation) focusing on cryptocurrency miners: examine System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx for executions of xmrig, cpuminer, or renamed mining binaries. 2. Analyze Sysmon EventID 3 network connections in the same log file for outbound connections to mining pool ports (3333, 4444, 5555) and suspicious IP addresses or domains containing ''pool'', ''mine'', or ''stratum''. 3. Check Windows Security Event Log (Security.evtx) for EventID 4698 (scheduled task creation) and correlate task actions with mining software execution paths. 4. Examine Prefetch files (C:/Windows/Prefetch/) for .pf files matching known mining software names or suspicious high-execution count binaries, and parse execution timestamps. 5. Review AmCache (C:/Windows/appcompat/Programs/Amcache.hve) for mining software installation artifacts and first execution timestamps. 6. For Linux systems, parse /var/log/audit/audit.log for execve syscalls launching mining processes and examine cron logs (/var/log/cron) for scheduled mining tasks.', '', 'name: Windows.Detection.ComputeHijacking
description: Detect cryptocurrency mining and compute hijacking activities across process creation, network connections, and scheduled tasks.
sources:
  - name: SuspiciousProcessCreation
    query: |
      SELECT System.TimeCreated.SystemTime AS Timestamp,
             EventData.Image AS ProcessPath,
             EventData.CommandLine AS CommandLine,
             EventData.ParentImage AS ParentProcess,
             EventData.ProcessId AS PID
      FROM parse_evtx(file=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID.Value = 1
        AND (
          EventData.Image =~ ''(?i)(xmrig|cpuminer|cgminer|bfgminer|sgminer|ccminer)''
          OR EventData.CommandLine =~ ''(?i)(stratum|mining|pool\\.|--donate-level|--algo)''
          OR (
            EventData.Image =~ ''(?i)(svchost|winlogon|csrss)\\.exe$''
            AND NOT EventData.ParentImage =~ ''(?i)(services|winlogon|system)''
          )
        )
        AND System.TimeCreated.SystemTime > now() - "7d"

  - name: MiningPoolConnections
    query: |
      SELECT System.TimeCreated.SystemTime AS Timestamp,
             EventData.Image AS ProcessPath,
             EventData.DestinationIp AS DestIP,
             EventData.DestinationPort AS DestPort,
             EventData.ProcessId AS PID
      FROM parse_evtx(file=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID.Value = 3
        AND (
          EventData.DestinationPort IN (''3333'', ''4444'', ''5555'', ''8333'', ''14433'')
          OR EventData.DestinationHostname =~ ''(?i)(pool|mine|stratum|xmr|btc|eth)''
          OR EventData.DestinationIp =~ ''^(45\\.|185\\.|192\\.)''
        )
        AND System.TimeCreated.SystemTime > now() - "7d"

  - name: SuspiciousScheduledTasks
    query: |
      SELECT System.TimeCreated.SystemTime AS Timestamp,
             EventData.TaskName AS TaskName,
             EventData.TaskContent AS TaskContent
      FROM parse_evtx(file=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE System.EventID.Value = 4698
        AND EventData.TaskContent =~ ''(?i)(xmrig|cpuminer|mining|stratum|pool)''
        AND System.TimeCreated.SystemTime > now() - "30d"', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1221', 'Template Injection', NULL, 'High', NULL, 243, 'Collect Sysmon Event Logs (WinEventLog:Sysmon) focusing on EventCode=1 for process creation, EventCode=3 for network connections, and EventCode=22 for DNS queries from Office applications. Gather Windows Security Event Log Event ID 4688 for additional process creation context. Collect suspicious Office documents and any referenced template files. Obtain browser cache contents from INetCache directories. Preserve network connection logs and DNS resolution logs. Collect Windows Registry NTUser hives for recent document access patterns. Gather any RTF files that may contain template injection via control words.', '1. Check Windows Event Logs for Sysmon Event ID 1 (Process Creation) where Office applications (winword.exe, excel.exe, powerpnt.exe) spawn child processes like powershell.exe or cmd.exe shortly after document opening. 2. Monitor Sysmon Event ID 3 (Network Connection) for Office processes making outbound HTTP/HTTPS connections to external domains immediately after document load, before macro execution. 3. Use netstat -ano to identify active connections from Office PIDs to external IPs during document processing. 4. Check running processes with Get-Process and correlate Office application PIDs with recent network activity in TCPView or equivalent. 5. Examine DNS query logs (Sysmon Event ID 22) for Office processes resolving external domains that may host malicious templates. 6. Review Windows Security Event ID 4688 for process creation events showing Office applications creating suspicious child processes.', '1. Extract and unzip suspicious Office documents (.docx, .xlsx, .pptx) and examine document/_rels/document.xml.rels or word/_rels/document.xml.rels for Target attributes containing external URLs in template references. 2. Parse Sysmon logs from Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx for Event IDs 1, 3, and 22 correlating Office process creation with network connections and DNS queries. 3. Analyze browser cache directories (Users/[user]/AppData/Local/Microsoft/Windows/INetCache) for downloaded template files that may contain malicious payloads. 4. Examine MFT entries for recently modified .dotx, .dotm template files and correlate timestamps with document opening events. 5. Review Windows Security logs for Event ID 4688 process creation events showing Office applications spawning unexpected child processes. 6. Check RTF documents for malicious \template control words using hex analysis to identify embedded URLs.', 'SELECT TimeCreated, System.Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ ''(?i)(winword|excel|powerpnt)\.exe$'' OR EventData.Image =~ ''(?i)(winword|excel|powerpnt)\.exe$'') AND (EventData.Image =~ ''(?i)(powershell|cmd|wscript|cscript|mshta)\.exe$'' OR EventData.CommandLine =~ ''(?i)(http|https|ftp)://'')', 'name: Windows.Detection.TemplateInjection
description: Detect Office Template Injection attacks through process and network correlation
imports:
  - Windows.EventLogs.Evtx
sources:
  - name: Office Process Creation
    query: |
      SELECT EventTime, Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId, EventData.ParentProcessId
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID.Value = 1 
      AND (EventData.ParentImage =~ ''(?i)(winword|excel|powerpnt)\.exe$'' OR EventData.Image =~ ''(?i)(winword|excel|powerpnt)\.exe$'')
      AND EventData.Image =~ ''(?i)(powershell|cmd|wscript|cscript|mshta)\.exe$''
  - name: Office Network Connections
    query: |
      SELECT EventTime, Computer, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.ProcessId
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID.Value = 3
      AND EventData.Image =~ ''(?i)(winword|excel|powerpnt)\.exe$''
      AND NOT EventData.DestinationIp =~ ''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.0\.0\.1)''
  - name: Office DNS Queries
    query: |
      SELECT EventTime, Computer, EventData.Image, EventData.QueryName, EventData.ProcessId
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID.Value = 22
      AND EventData.Image =~ ''(?i)(winword|excel|powerpnt)\.exe$''', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('REGISTRY_SOFTWARE', 'Registry - SOFTWARE', 'Windows', 'High', NULL, 885, NULL, NULL, NULL, 'SELECT Key.FileInfo.FullPath AS KeyPath, Key.FileInfo.ModTime AS KeyModTime, Key.Values AS Values FROM read_reg_key(root=''HKEY_LOCAL_MACHINE'', globs=''SOFTWARE/**'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('REGISTRY_CLASSES_ROOT', 'Registry - CLASSES_ROOT', 'Windows', 'Medium', NULL, 893, NULL, NULL, NULL, 'SELECT Key.FileInfo.FullPath AS KeyPath, Key.FileInfo.ModTime AS KeyModTime, Key.Values AS Values FROM read_reg_key(root=''HKEY_CLASSES_ROOT'', globs=''**'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('REGISTRY_CURRENT_CONFIG', 'Registry - CURRENT_CONFIG', 'Windows', 'Low', NULL, 894, NULL, NULL, NULL, 'SELECT Key.FileInfo.FullPath AS KeyPath, Key.FileInfo.ModTime AS KeyModTime, Key.Values AS Values FROM read_reg_key(root=''HKEY_LOCAL_MACHINE'', globs=''SYSTEM/CurrentControlSet/Hardware Profiles/Current/**'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('EVENT_LOGS_APPLICATION', 'Event Logs - Application', 'Windows', 'High', NULL, 877, NULL, NULL, NULL, 'SELECT System.TimeCreated.SystemTime AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value AS EventID, System.EventRecordID AS EventRecordID, System.Security.UserID AS UserID, Message FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Application.evtx'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('EVENT_LOGS_SYSMON', 'Event Logs - Sysmon', 'Windows', 'High', NULL, 878, NULL, NULL, NULL, 'SELECT System.TimeCreated.SystemTime AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value AS EventID, System.EventRecordID AS EventRecordID, System.Security.UserID AS UserID, Message FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('EVENT_LOGS_POWERSHELL', 'Event Logs - PowerShell', 'Windows', 'High', NULL, 879, NULL, NULL, NULL, 'SELECT System.TimeCreated.SystemTime AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value AS EventID, System.EventRecordID AS EventRecordID, System.Security.UserID AS UserID, Message FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('SRUM', 'Triage - SRUM', 'Windows', 'Medium', NULL, 847, NULL, NULL, NULL, 'SELECT AutoIncId, TimeStamp, AppId, UserId, BytesSent, BytesRecvd FROM parse_ese(file=''C:/Windows/System32/sru/SRUDB.dat'', accessor=''ntfs'', table=''{973F5D5C-1D90-4944-BE8E-24B94231A174}'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('USB_ARTIFACTS', 'Triage - USB Artifacts', 'Windows', 'Medium', NULL, 850, NULL, NULL, NULL, 'SELECT Key.FileInfo.FullPath AS FullPath, Key.FileInfo.ModTime AS ModTime, * FROM read_reg_key(root=''HKEY_LOCAL_MACHINE'', globs=''SYSTEM/CurrentControlSet/Enum/USBSTOR/**'')', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('BROWSER_FIREFOX', 'Browser Artifacts - Firefox', 'Windows', 'Medium', NULL, 891, NULL, NULL, NULL, 'SELECT * FROM foreach(row={SELECT FullPath FROM glob(globs=''C:/Users/*/AppData/Roaming/Mozilla/Firefox/Profiles/*/places.sqlite'')}, query={SELECT url, title, visit_count, last_visit_date FROM sqlite(file=FullPath, query=''SELECT url, title, visit_count, last_visit_date FROM moz_places WHERE visit_count > 0'')})', NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1055.005', 'Thread Local Storage', 'Windows/Linux', 'Medium', 'Review system artifacts.', 568, 'Collect Sysmon Event Logs focusing on EventCode=7 (Image loaded), EventCode=8 (CreateRemoteThread), and EventCode=10 (ProcessAccess) from WinEventLog:Sysmon channel. Gather EDR memory telemetry specifically MemoryWriteToExecutable events targeting PE header regions. Collect full memory dumps of suspicious processes for offline TLS directory analysis. Retrieve Windows System Event Log for process creation correlation. Collect recent PE files from temp directories, downloads, and quarantine locations. Gather MFT and USN journal entries for file modification timeline analysis. Include prefetch files and shimcache registry entries for execution artifact correlation.', '1. Monitor Sysmon Event ID 7 (Image loaded) for unusual DLL loads followed immediately by Event ID 8 (CreateRemoteThread) or Event ID 10 (ProcessAccess) targeting the same process. 2. Examine running processes using Process Hacker or similar tools to inspect TLS callback addresses in PE headers - look for callbacks pointing to unexpected memory regions or recently allocated RWX memory. 3. Use WinDbg or x64dbg to attach to suspicious processes and examine the TLS directory structure at runtime, checking if AddressOfCallBacks points to non-standard locations. 4. Monitor for processes with threads executing before reaching the main entry point using Performance Toolkit (WPT) or ETW tracing. 5. Check for memory modifications in .tls or .data sections of loaded PE files using tools like Hollows Hunter or Pe-sieve. 6. Correlate timeline between image load events and subsequent memory write operations to executable sections within the same process.', '1. Parse Sysmon logs from Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx focusing on Event IDs 7, 8, and 10 sequences within tight timeframes on the same ProcessId. 2. Extract and analyze PE files from quarantine, temp directories, or recent file system activity for modified TLS directory structures using tools like PEStudio or CFF Explorer. 3. Examine MFT entries and USN journal for recently modified executable files, particularly focusing on timestamp anomalies that suggest post-load modification. 4. Analyze memory dumps from crash dumps or hibernation files, searching for PE headers with suspicious TLS callback pointers using Volatility''s malfind or hollowfind plugins. 5. Review Windows Event Log System channel for process creation events correlated with the timeline of suspected TLS callback injection. 6. Check prefetch files (.pf) in Windows/Prefetch for execution patterns of known good processes that may have been targeted for injection.', NULL, 'name: Windows.Detection.TLSCallbackInjection
description: Detect TLS callback injection by correlating Sysmon image loads with process access and thread creation events
sources:
  - name: SysmonImageLoads
    query: |
      SELECT System.TimeCreated as LoadTime, EventData.ProcessId, EventData.Image, EventData.ImageLoaded, EventData.ProcessGuid
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID = 7
  - name: SysmonProcessAccess
    query: |
      SELECT System.TimeCreated as AccessTime, EventData.SourceProcessId, EventData.TargetProcessId, EventData.GrantedAccess, EventData.CallTrace
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID = 10 AND EventData.GrantedAccess =~ ''0x1F3FFF|0x001F0FFF''
  - name: SysmonThreadCreation
    query: |
      SELECT System.TimeCreated as ThreadTime, EventData.SourceProcessId, EventData.TargetProcessId, EventData.StartAddress, EventData.StartModule
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID = 8', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1480.002', 'Execution Guardrails: Environmental Keying', NULL, 'Medium', NULL, 516, 'Collect Sysmon EventCode=1 (process creation) and EventCode=11 (file creation) from WinEventLog:Sysmon channel. Gather auditd SYSCALL logs for open, flock, fcntl, unlink, and exit_group system calls on Linux. Collect macOS unified logs filtering for flock, NSDistributedLock, and FileHandle lockForWriting patterns. Target mutex creation in Windows via kernel object monitoring and file lock acquisition in Unix-like systems via system call auditing. Include process termination events correlated within short time windows of mutex/lock operations.', '1. Monitor active processes for mutex creation using Sysmon EventID 1 and look for CreateMutex/CreateMutexW API calls in process command lines or loaded modules. 2. Check running processes that exit quickly after startup using ''wevtutil qe Microsoft-Windows-Sysmon/Operational /q:"*[System[EventID=5]]"'' and correlate with recent process creation events. 3. Use Process Monitor to track mutex object creation in real-time, filtering for Global\ or Local\ named mutexes with suspicious high-entropy names. 4. On Linux systems, monitor /proc/locks for file locks and correlate with processes in /proc/*/cmdline that exit rapidly. 5. Check for temporary lock files in /tmp, /var/tmp, or /var/run directories that appear and disappear quickly using ''lsof +D /tmp'' and file system monitoring.', '1. Parse Sysmon logs (EventID 1, 11) from Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx for mutex creation patterns followed by rapid process termination within short timeframes. 2. Examine prefetch files in Windows/Prefetch/ for executables with very low run counts but recent timestamps, indicating processes that check for existing instances and exit. 3. Analyze Linux auditd logs in /var/log/audit/audit.log for SYSCALL records showing open(), flock(), fcntl() operations on lock files followed by exit_group() calls. 4. Search MFT entries and USN journal for temporary lock files created and deleted quickly in suspicious locations like /tmp/.lock* patterns. 5. Review application crash dumps and memory images for mutex handles and named objects that indicate mutual exclusion logic.', 'SELECT System.TimeCreated AS SystemTime, EventData.ProcessId, EventData.Image, EventData.CommandLine, EventData.ParentImage FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ ''CreateMutex'' OR EventData.CommandLine =~ ''Global\\'' OR EventData.CommandLine =~ ''Local\\'')', 'name: Mutex.ExecutionGuardrails
description: Detect mutex-based execution guardrails across Windows and Linux platforms
sources:
  - name: Windows_Sysmon_Mutex
    query: |
      SELECT System.TimeCreated.SystemTime AS Timestamp,
             EventData.ProcessId,
             EventData.Image,
             EventData.CommandLine,
             EventData.ParentProcessId,
             ''Windows'' AS Platform
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID = 1 AND 
            (EventData.CommandLine =~ ''CreateMutex|Global\\|Local\\'' OR
             EventData.Image =~ ''\\tmp\\|\\temp\\'')
      ORDER BY Timestamp DESC
  - name: Linux_Auditd_FileLocks
    query: |
      SELECT timestamp,
             pid,
             exe,
             syscall,
             a0 AS filename,
             exit AS exit_code,
             ''Linux'' AS Platform
      FROM Linux.Events.Journal()
      WHERE syscall IN (''open'', ''flock'', ''fcntl'') AND
            (filename =~ ''/tmp/\.lock|/var/run/.*lock|/tmp/.*\.mutex'')
      ORDER BY timestamp DESC', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1133', 'External Remote Services', NULL, 'Critical', NULL, 178, 'Collect Security.evtx (Event IDs 4624, 4625, 4776), RdpCoreTS/Operational.evtx (Event ID 131), TerminalServices-RemoteConnectionManager/Operational.evtx (Event ID 1149), and Application.evtx for VPN/Citrix gateway logs. For Linux systems, collect /var/log/auth.log, /var/log/secure, auditd logs with SYSCALL records for SSH connections, and syslog entries. Gather registry hives focusing on Terminal Server configuration keys and software installation keys for remote access tools. For containers, collect Docker API logs, Kubernetes audit logs, and kubelet logs. Include network flow data showing inbound connections to common remote access ports (3389, 22, 5900, 2375, 6443). Collect VPN concentrator logs and firewall logs showing external-to-internal connections if available.', '1. Check current external RDP connections using ''netstat -an | findstr :3389'' and ''qwinsta'' to identify active remote sessions. 2. Query Security event log for recent external logons: ''Get-WinEvent -FilterHashtable @{LogName=''Security'';ID=4624,4625;StartTime=(Get-Date).AddDays(-7)} | Where-Object {$_.Properties[18].Value -like ''*.*.*.*'' -and $_.Properties[8].Value -eq 10}'' to find Type 10 (RemoteInteractive) logons. 3. Examine failed authentication attempts: ''Get-WinEvent -FilterHashtable @{LogName=''Security'';ID=4625;StartTime=(Get-Date).AddHours(-24)}'' and correlate source IPs with successful logons. 4. Check for VPN client software and connections in running processes: ''Get-Process | Where-Object {$_.ProcessName -match ''vpn|citrix|teamviewer|anydesk''}'' and review network connections. 5. For Linux systems, examine active SSH sessions with ''who -a'' and ''ss -tuln'' for listening services, then check ''/var/log/auth.log'' for recent SSH authentication attempts. 6. Review system timezone and compare with logon times to identify off-hours access patterns that may indicate compromise.', '1. Extract and parse Security.evtx focusing on Event IDs 4624 (successful logon), 4625 (failed logon), and 4776 (credential validation) with Logon Type 10 (RemoteInteractive) or 3 (Network) from external IPs. 2. Analyze TerminalServices-RemoteConnectionManager/Operational.evtx Event ID 1149 and RdpCoreTS/Operational.evtx Event ID 131 to identify remote connection source IPs and connection times. 3. Parse registry keys HKLM\SYSTEM\CurrentControlSet\Control\Terminal Server and HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Terminal Server for RDP configuration changes. 4. Examine VPN client artifacts in Program Files, AppData, and registry entries for Cisco AnyConnect, OpenVPN, or other remote access tools including connection logs. 5. For containerized environments, analyze Docker daemon logs at /var/log/docker.log and Kubernetes audit logs for external API access attempts to ports 2375, 2376, or 6443. 6. Cross-reference MFT entries and USN journal for timeline analysis of remote access tool installation or configuration changes around suspected compromise timeframes.', 'SELECT TimeCreated, System.Computer, System.EventID.Value, Channel, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName, EventData.WorkstationName, EventData.LogonProcessName FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE System.EventID.Value IN (4624, 4625, 4776) AND EventData.LogonType IN (3, 10, 12) AND EventData.IpAddress =~ ''^(?!10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.).*'' AND EventData.IpAddress != ''-'' AND EventData.IpAddress != ''127.0.0.1''', 'name: Hunt.T1133.ExternalRemoteServices
description: Detect external remote service access across multiple platforms and services
imports:
  - Windows.EventLogs.Evtx
sources:
  - name: Windows_RDP_Connections
    query: |
      SELECT EventTime, Computer, EventID, Channel, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName, EventData.ProcessName
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE (EventID IN (4624, 4625) AND EventData.LogonType IN (3, 10, 12)) OR EventID IN (131, 1149)
      AND if(condition=EventData.IpAddress, then=EventData.IpAddress =~ ''^(?!10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.).*'' AND EventData.IpAddress != ''-'', else=TRUE)
  - name: Linux_SSH_Access
    query: |
      SELECT Timestamp, Hostname, Message, Tag
      FROM source(artifact=''Linux.Events.Journal'')
      WHERE Message =~ ''(?i)(sshd|ssh).*((failed|accepted).*password|connection.*from)''
      OR Message =~ ''addr=[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+''
  - name: Container_API_Access
    query: |
      SELECT Timestamp, Message, Source
      FROM Artifact.Generic.System.Pstree()
      WHERE Message =~ ''(?i)(docker|kubectl|kubernetes).*api''
      OR Message =~ ''port.*(2375|2376|6443|10250)''', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1203', 'Exploitation for Client Execution', NULL, 'Critical', NULL, 212, 'Collect Windows Application Event Log (Event IDs 1000, 1001 for application crashes). Collect Sysmon logs focusing on Event ID 1 (Process Creation), Event ID 11 (File Creation), Event ID 3 and 22 (Network Connections). Target user-writable paths: Downloads folder, %TEMP%, %APPDATA%, Office startup folders. For Linux: collect syslog for crash/segfault messages, auditd SYSCALL events for open/creat/execve/rename/chmod. For macOS: collect unified logs for process crashes and code signing violations, fsevents for file creation/modification in ~/Library and ~/Downloads. Include browser history databases, Office recent files, and email attachments. Prioritize correlation within 15-30 minute time windows around suspicious application behavior.', '1. Check for application crashes using ''Get-WinEvent -LogName Application -FilterHashtable @{ID=1000,1001} | Where-Object {$_.Message -match "(iexplore|chrome|firefox|winword|excel|powerpnt|acrord32)"} | Select-Object -First 20''. 2. Monitor for unexpected child processes from client apps using ''Get-Process | Where-Object {$_.ProcessName -match "(iexplore|chrome|firefox|winword|excel|powerpnt)"} | ForEach-Object {Get-WmiObject -Query "SELECT * FROM Win32_Process WHERE ParentProcessId=$($_.Id)"} | Where-Object {$_.Name -match "(cmd|powershell|wscript|mshta|rundll32)"}''. 3. Check recent file writes in user-writable locations using ''Get-ChildItem -Path "$env:USERPROFILE\Downloads","$env:TEMP","$env:APPDATA" -Recurse | Where-Object {$_.LastWriteTime -gt (Get-Date).AddHours(-2)} | Sort-Object LastWriteTime -Descending''. 4. Look for network connections from client applications using ''netstat -ano | findstr ESTABLISHED'' and correlate PIDs with browser/office processes. 5. Check for exploit-related registry modifications in ''HKCU\Software\Microsoft\Office'' and browser extension paths using appropriate reg query commands.', '1. Parse Application.evtx for Event IDs 1000 and 1001, filtering for faulting applications like iexplore.exe, chrome.exe, firefox.exe, winword.exe, excel.exe, powerpnt.exe, acrord32.exe to identify crashes during exploitation timeframe. 2. Examine MFT entries for recently created files in %USERPROFILE%\Downloads, %TEMP%, %APPDATA%, and Office startup folders, looking for executable files, scripts, or documents with suspicious creation times. 3. Analyze Sysmon logs (if available) for Event ID 1 (Process Creation) showing client applications spawning unusual child processes like cmd.exe, powershell.exe, wscript.exe, mshta.exe, rundll32.exe. 4. Review Sysmon Event ID 11 (File Creation) for files written by browser or office processes to unusual locations or with executable extensions. 5. Check Sysmon Event ID 3 (Network Connection) for outbound connections initiated by client applications to non-standard domains or IP ranges. 6. Examine browser cache, downloads database, and Office recent files registry keys for evidence of malicious document delivery.', 'SELECT EventTime, Computer, System.EventID.Value, EventData.Application as FaultingApp, EventData.ModuleName as FaultingModule, EventData.ApplicationPath, EventData.FaultingApplicationStartTime FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Application.evtx'') WHERE LogFile = ''Application.evtx'' AND System.EventID.Value IN (1000, 1001) AND EventData.Application =~ ''(?i)(iexplore|chrome|firefox|msedge|winword|excel|powerpnt|acrord32|flashplayerplugin)'' ORDER BY EventTime DESC', 'name: Windows.Custom.ClientExploitChain
description: Detects exploitation for client execution by correlating application crashes, suspicious child processes, file writes, and network connections.
sources:
  - name: ApplicationCrashes
    query: |
      SELECT System.TimeCreated.SystemTime AS Timestamp,
             System.Computer AS Computer,
             EventData.Application AS App,
             EventData.ModuleName AS ModuleName,
             EventData.ApplicationPath AS AppPath
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Application.evtx'')
      WHERE System.EventID IN (1000, 1001)
        AND EventData.Application =~ ''(?i)(iexplore|chrome|firefox|winword|excel|powerpnt|acrord32)''
  - name: SuspiciousChildren
    query: |
      SELECT System.TimeCreated.SystemTime AS Timestamp,
             System.Computer AS Computer,
             EventData.Image AS ProcessName,
             EventData.ParentImage AS ParentImage,
             EventData.CommandLine AS CommandLine
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID = 1
        AND EventData.ParentImage =~ ''(?i)(iexplore|chrome|firefox|winword|excel|powerpnt|acrord32)''
        AND EventData.Image =~ ''(?i)(cmd|powershell|wscript|mshta|rundll32)\.exe$''
  - name: FileWrites
    query: |
      SELECT System.TimeCreated.SystemTime AS Timestamp,
             System.Computer AS Computer,
             EventData.TargetFilename AS TargetFilename,
             EventData.Image AS Image
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID = 11
        AND EventData.Image =~ ''(?i)(iexplore|chrome|firefox|winword|excel|powerpnt|acrord32)''
        AND (EventData.TargetFilename =~ ''(?i)Downloads''
             OR EventData.TargetFilename =~ ''(?i)\\Temp\\''
             OR EventData.TargetFilename =~ ''(?i)\\AppData\\'')
  - name: NetworkConnections
    query: |
      SELECT System.TimeCreated.SystemTime AS Timestamp,
             System.Computer AS Computer,
             EventData.Image AS Image,
             EventData.DestinationIp AS DestIP,
             EventData.DestinationPort AS DestPort
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID = 3
        AND EventData.Image =~ ''(?i)(iexplore|chrome|firefox|winword|excel|powerpnt|acrord32)''
        AND NOT EventData.DestinationIp =~ ''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.)''
', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1011.001', 'Exfiltration Over Bluetooth', 'Windows/Linux', 'Medium', 'Review system artifacts.', 531, 'Collect Windows System Event Log (EventCode=8001) for Bluetooth service activities. Gather Sysmon Event ID 1 (Process Creation) and Event ID 11 (File Creation) from WinEventLog:Sysmon channel. For Linux environments, collect auditd SYSCALL logs and linux:syslog entries. Obtain macOS unified logs and osquery data. Specific registry collection should include HKLM\SYSTEM\CurrentControlSet\Services\BthServ and Bluetooth device enumeration keys. Collect process execution logs focusing on bthserv.exe, fsquirt.exe, hcitool, bluetoothctl, rfcomm, blueutil, and networksetup commands.', '1. Check active Bluetooth devices and connections using ''Get-PnpDevice -Class Bluetooth'' and ''Get-NetAdapter | Where-Object {$_.InterfaceDescription -like ''*Bluetooth*''}'' to identify active BT interfaces. 2. Monitor Sysmon Event ID 1 (Process Creation) for processes accessing Bluetooth drivers or utilities like bthserv.exe, fsquirt.exe. 3. Review System Event Log for Event ID 8001 (Bluetooth service activities) and filter for connection establishment events. 4. Check running processes accessing bthport.sys driver using ''Get-Process | Get-ProcessModule | Where-Object {$_.ModuleName -like ''*bth*''}''. 5. On Linux systems, monitor for hcitool, bluetoothctl, rfcomm command execution via ''ps aux | grep -E "(hcitool|bluetoothctl|rfcomm)"''. 6. Correlate recent large file access with Bluetooth activity within configurable time windows.', '1. Parse Windows System Event Log for Event ID 8001 entries showing Bluetooth device pairing and data transfer activities, focusing on timestamps around suspected exfiltration periods. 2. Extract Sysmon Event ID 1 (Process Creation) and Event ID 11 (File Creation) logs to identify processes that accessed both sensitive files and Bluetooth interfaces. 3. Examine registry keys HKLM\SYSTEM\CurrentControlSet\Services\BthServ and HKLM\SYSTEM\CurrentControlSet\Enum\BTHENUM for paired device history and connection logs. 4. On Linux systems, parse auditd SYSCALL records for execve calls to Bluetooth utilities and correlate with file access syscalls. 5. Review /var/log/syslog entries for Bluetooth kernel module activities and device connection events. 6. Analyze MFT entries and file access timestamps for sensitive files accessed near Bluetooth activity timeframes.', 'SELECT timestamp, System.EventID.Value as EventID, System.Provider.Name as Provider, EventData.Data as EventData FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/System.evtx'') WHERE System.EventID.Value = 8001 AND Provider =~ "bth|bluetooth"', 'name: Custom.Detection.BluetoothExfiltration
description: |
   Detect potential data exfiltration over Bluetooth by correlating
   Bluetooth activity with file access events across multiple log sources.
   
sources:
  - name: WindowsBluetoothEvents
    query: |
      SELECT timestamp, System.EventID.Value as EventID, 
             System.Provider.Name as Provider,
             EventData.Data as EventData
      FROM source(artifact="Windows.EventLogs.Evtx", source="System")
      WHERE EventID = 8001 AND Provider =~ "bth|bluetooth"
      
  - name: SysmonFileAndProcess
    query: |
      SELECT timestamp, System.EventID.Value as EventID,
             EventData.Image, EventData.TargetFilename,
             EventData.ProcessId
      FROM source(artifact="Windows.EventLogs.Evtx", source="Microsoft-Windows-Sysmon/Operational")
      WHERE EventID IN (1, 11) AND (EventData.Image =~ "bth|bluetooth" OR EventData.CommandLine =~ "bthserv|fsquirt")
      
  - name: LinuxBluetoothCommands
    query: |
      SELECT timestamp, exe, cmdline, uid
      FROM source(artifact="Linux.Events.Journal")
      WHERE exe =~ "(hcitool|bluetoothctl|rfcomm|obexftp)$"', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1066', 'Indicator Removal from Tools', NULL, 'Critical', NULL, 100, 'Perform raw disk carving for deleted files and capture the USN Journal before it is cycled or deleted.', '1. Monitor for the deletion of binaries immediately after execution (e.g., a script that runs ''del %0'').
2. Watch for ''fsutil usn deletejournal'' which wipes the evidence of file creations.', '1. Analyze the $MFT for ''orphan'' entries or a high number of ''File Deleted'' flags in the same directory where a breach was suspected.
2. Search Security logs for Event ID 1102 (The audit log was cleared).', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1067', 'Bootkit', NULL, 'Critical', NULL, 101, 'Forensic image of the physical drive (first 100 sectors) and the EFI System Partition (ESP).', '1. Use ''bootkit_verify'' or similar tools to check the integrity of the MBR/VBR against a known-good signature.
2. Monitor for unauthorized writes to the physical drive handle (\\.\PhysicalDriveX) using Sysmon ID 9 (RawAccessRead).', '1. Compare the first 512 bytes of the physical drive with a standard Windows MBR to identify malicious bootstrap code.
2. Inspect the UEFI firmware variables in the SYSTEM hive for unauthorized ''BootOrder'' modifications.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1070.001', 'Indicator Removal: Clear Windows Event Logs', NULL, 'Critical', NULL, 107, 'Mandatory: Collect all .evtx files from the winevt/logs directory.', '1. Search for Event ID 1102 (Security log cleared) or Event ID 104 (System log cleared).
2. Monitor for ''wevtutil.exe cl'' or ''Clear-EventLog'' execution.', '1. Look for gaps in the Record ID sequence within the .evtx files.
2. Use ''EvtxECmd'' to find ''Unused'' or ''Slack'' space in the event log files that might contain fragments of the deleted logs.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1023', 'Shortcut Modification', 'Windows/Linux', 'Medium', 'Review system artifacts.', 538, 'Standard Triage', 'Scan for .lnk files with cmd/ps1 args.', 'Parse Recent Items and Desktop LNK files.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1165', 'Startup Items', 'Cross-Platform', 'Low', 'Perform baseline triage.', 680, 'General Collection', 'Review logs for execution.', 'Search disk for file modifications.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1608.005', 'Link Target', 'Cross-Platform', 'Low', 'Perform baseline triage.', 753, 'Collect Internet Scan data as specified in MITRE log sources, focusing on external threat intelligence and internet scanning results. Collect browser history and cache files from all user profiles. Gather DNS query logs from Microsoft-Windows-DNS-Client/Operational event channel. Collect email artifacts including PST/OST files and webmail cache. Preserve network logs from security appliances, proxy servers, and DNS servers. Collect SRUM database for network connection artifacts.', '1. Monitor network connections for suspicious outbound traffic to newly registered domains using ''netstat -an'' and network monitoring tools. 2. Check browser history and temporary files for recently visited suspicious URLs in user profiles under %USERPROFILE%\AppData\Local\Microsoft\Windows\WebCache\WebCacheV*.dat. 3. Review DNS query logs in Windows Event Log (Microsoft-Windows-DNS-Client/Operational) for queries to suspicious domains. 4. Examine running processes for browser instances or network activity using ''tasklist /svc'' and ''wmic process list full''. 5. Check proxy logs and network security appliance logs for blocked or flagged URLs in real-time.', '1. Parse browser artifacts including history databases, cache files, and downloads from Chrome (\Users\*\AppData\Local\Google\Chrome\User Data\Default\History), Firefox (\Users\*\AppData\Roaming\Mozilla\Firefox\Profiles\*\places.sqlite), and Edge locations. 2. Examine email artifacts in PST/OST files and webmail cache for spearphishing messages containing malicious links. 3. Analyze Windows Event Logs, specifically Microsoft-Windows-DNS-Client/Operational (Event ID 3008) for DNS queries to suspicious domains. 4. Review MFT entries for recently created or modified files in temporary directories and browser cache locations. 5. Extract and analyze network artifacts from SRUM database (\Windows\System32\sru\SRUDB.dat) for network connections to staging infrastructure.', 'SELECT System.TimeCreated AS SystemTime, EventData.QueryName as DomainQueried, EventData.QueryType as QueryType, System.Computer as Hostname FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client/Operational.evtx'') WHERE System.EventID.Value = 3008 AND EventData.QueryName =~ ''(?i)(bit\.ly|tinyurl|goo\.gl|t\.co|short|redirect)'' OR EventData.QueryName =~ ''(?i)[0-9a-f]{8,}\.'' OR len(str=EventData.QueryName) > 50', 'name: Windows.Custom.LinkTargetAnalysis
description: Detect staging of malicious link targets through DNS queries, browser activity, and network connections
imports:
  - Windows.EventLogs.Evtx
  - Windows.Forensics.Srum
sources:
  - name: SuspiciousDNSQueries
    query: |
      SELECT System.TimeCreated as Timestamp, EventData.QueryName as Domain, EventData.QueryType as Type, System.Computer as Host
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE System.EventID = 3008 AND (EventData.QueryName =~ ''(?i)(bit\.ly|tinyurl|goo\.gl|t\.co|short|redirect)'' OR EventData.QueryName =~ ''(?i)[0-9a-f]{8,}\.'' OR len(list=EventData.QueryName) > 50)
  - name: BrowserHistoryAnalysis
    query: |
      SELECT url, title, visit_count, last_visit_time, typed_count
      FROM sqlite(file=expand(path=''%USERPROFILE%/AppData/Local/Google/Chrome/User Data/Default/History''), query=''SELECT url, title, visit_count, last_visit_time, typed_count FROM urls'')
      WHERE url =~ ''(?i)(bit\.ly|tinyurl|goo\.gl|t\.co|short|redirect)'' OR url =~ ''(?i)https?://[0-9a-f]{8,}\.'' OR len(list=url) > 100
  - name: NetworkConnections
    query: |
      SELECT TimeStamp, AppId, ConnectedTime, ConnectStartTime, InterfaceLuid, L2ProfileId
      FROM source(artifact=''Windows.Forensics.Srum'')
      WHERE AppId =~ ''(?i)(chrome|firefox|edge|iexplore)'' AND ConnectedTime > 0', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1211', 'Exploitation for Client Execution', NULL, 'Critical', NULL, 221, 'Collect Windows Security Event Log (EventID 4688 for process creation), Windows Application Event Log (EventID 1000/1001 for crashes), Sysmon Event Log (EventID 7 for image/DLL loads), Windows System Event Log (EventID 7034/7036 for service changes). On Linux systems collect auditd SYSCALL records for execve events and syslog entries showing segfaults/crashes of security daemons. For macOS collect unified logs filtering for com.apple.security.* daemon terminations and osquery process execution data. Cloud environments require AWS CloudTrail logs focusing on StopLogging/DeleteTrail/UpdateTrail API calls, and for SaaS collect M365 unified audit logs for ApplicationModified/ConsentGranted events. Include Windows Error Reporting files from %ProgramData%\Microsoft\Windows\WER and any available crash dumps.', '1. Check for abnormal termination of defensive processes using ''Get-WinEvent -LogName Application -FilterHashtable @{ID=1000}'' to identify crashes of AV/EDR processes. 2. Examine running processes for unsigned modules loaded into security software using ''Get-Process | Where-Object {$_.ProcessName -match "defender|symantec|mcafee"} | Get-ProcessModule'' and verify digital signatures. 3. Monitor for privilege escalation from security agent services using ''Get-WinEvent -LogName Security -FilterHashtable @{ID=4672}'' focusing on security service accounts gaining unexpected privileges. 4. Check for gaps in security logging by comparing expected vs actual log volumes using ''Get-WinEvent -LogName "Microsoft-Windows-Windows Defender/Operational"'' for recent time windows. 5. Identify processes attempting to modify or disable security services using ''Get-WinEvent -LogName System -FilterHashtable @{ID=7034,7036}'' for unexpected service state changes.', '1. Parse Windows Event Logs (Security.evtx, Application.evtx, System.evtx) focusing on EventID 4688 for process creation around defensive software crashes and EventID 1000/1001 for application error events. 2. Examine Sysmon logs (Microsoft-Windows-Sysmon%4Operational.evtx) for EventID 7 (Image/DLL loaded) showing unsigned or suspicious modules loaded into AV/EDR processes. 3. Analyze Windows Error Reporting artifacts in %ProgramData%\Microsoft\Windows\WER for crash dumps of security software processes, including Report.wer files and memory dumps. 4. Review MFT entries and file system timeline for modifications to security software binaries in %ProgramFiles% and %ProgramFiles(x86)% directories during suspected timeframe. 5. Extract and analyze any available memory dumps of crashed security processes for signs of exploitation, focusing on heap/stack corruption patterns and injected code.', 'SELECT TimeCreated, System.Computer, EventData, UserData FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Application.evtx'') WHERE System.EventID.Value = 1000 AND EventData.ApplicationName =~ ''(?i)(defender|symantec|mcafee|crowdstrike|carbon|sentinel)''', 'name: Windows.Custom.DefenseEvasionExploitation
description: Detect exploitation attempts against defensive security software through process crashes and module loading
sources:
  - name: SecurityProcessCrashes
    query: |
      SELECT EventTime, Computer, EventData.ApplicationName as CrashedApp, EventData.FaultingModule as FaultModule
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Application.evtx'')
      WHERE System.EventID.Value = 1000
        AND EventData.ApplicationName =~ ''(?i)(defender|symantec|mcafee|crowdstrike|carbon|sentinel|kaspersky)''
        AND EventTime > now() - 604800
  - name: SuspiciousModuleLoads
    query: |
      SELECT EventTime, Computer, EventData.Image as TargetProcess, EventData.ImageLoaded as LoadedModule, EventData.Signed
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID.Value = 7
        AND EventData.Image =~ ''(?i)(defender|symantec|mcafee|crowdstrike|carbon|sentinel)''
        AND (EventData.Signed = ''false'' OR EventData.ImageLoaded =~ ''(?i)(temp|appdata|programdata)'')
        AND EventTime > now() - 604800
  - name: PrivilegeEscalation
    query: |
      SELECT EventTime, Computer, EventData.SubjectUserName, EventData.PrivilegeList
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE System.EventID.Value = 4672
        AND EventData.SubjectUserName =~ ''(?i)(system|defender|av|security)''
        AND EventTime > now() - 604800', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1560.002', 'Archive Collected Data: Archive via Library', NULL, 'Medium', NULL, 517, 'Collect Windows Security Event Log (Event ID 4688 process creation), Sysmon Operational Log (Event IDs 1, 7, 11 for process creation, image loads, file creation), PowerShell Operational and Analytic logs for script execution. On Linux systems, collect auditd logs for execve syscalls, mmap events for library loading (libzip.so, libz.so, libbz2.so), and file creation events. For macOS, gather unified logs showing process execution, dylib loading (libz.dylib, libarchive.dylib), and file creation events. Include MFT, USN Journal, prefetch files, and PowerShell history artifacts for comprehensive timeline reconstruction.', '1. Monitor process creation for Python/PowerShell scripts using Sysmon Event ID 1, correlating with Sysmon Event ID 7 (Image/Module Load) for compression libraries (zlib.dll, System.IO.Compression). 2. Check running processes with ''Get-Process | Where-Object {$_.Modules -match "zip|compress|archive"}'' to identify active compression library usage. 3. Monitor file system activity using Sysmon Event ID 11 for archive creation (.zip, .rar, .7z) in staging directories like %TEMP%, %APPDATA%. 4. Examine Security Event ID 4688 process creation logs for suspicious script interpreters (python.exe, powershell.exe) with command lines containing archive-related imports. 5. Use Process Monitor to track real-time file I/O operations showing data collection followed by archive creation patterns.', '1. Parse MFT entries for recently created archive files (.zip, .rar, .7z, .gz) in staging locations (%TEMP%, %APPDATA%, user directories) with timestamps correlating to potential data collection periods. 2. Extract and analyze Windows Event Logs (Security.evtx, Microsoft-Windows-Sysmon%4Operational.evtx) for Event IDs 4688, 1, 7, and 11 showing script execution, library loads, and file creation sequences. 3. Search for PowerShell script artifacts in ConsoleHost_history.txt and PowerShell Operational logs containing compression cmdlets or .NET compression classes. 4. Examine prefetch files for python.exe, powershell.exe execution with parameters indicating archive operations. 5. Analyze USN journal entries for rapid file access patterns followed by archive creation in suspicious locations.', 'LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 1 AND (EventData.Image =~ ''(?i)(python|powershell|cscript|wscript)\.exe$'' AND EventData.CommandLine =~ ''(?i)(zip|compress|archive|gzip|bzip|rarfile|libzip|zlib)'') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ ''(?i)(python|powershell|cscript|wscript)\.exe$'' AND EventData.CommandLine =~ ''(?i)(zip|compress|archive|gzip|bzip|rarfile|libzip|zlib)'') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})', 'name: Custom.T1560.002.ArchiveViaLibrary
description: Detect archive operations using compression libraries across process creation, module loads, and file creation
sources:
  - name: ProcessCreation
    query: |
      SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer, EventData.NewProcessName, EventData.CommandLine, EventData.ProcessId AS PID
      FROM source(artifact="Windows.EventLogs.Evtx", source="Microsoft-Windows-Sysmon/Operational")
      WHERE System.EventID = 1 AND (EventData.Image =~ "(?i)(python|powershell|cscript)\.exe$" AND EventData.CommandLine =~ "(?i)(zip|compress|archive|rarfile|libzip|zlib)")
  - name: ModuleLoads
    query: |
      SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, EventData.ProcessId AS PID, EventData.Image, EventData.ImageLoaded
      FROM source(artifact="Windows.EventLogs.Evtx", source="Microsoft-Windows-Sysmon/Operational")
      WHERE System.EventID = 7 AND EventData.ImageLoaded =~ "(?i)(zlib|compress|archive|zip)\.dll$"
  - name: FileCreation
    query: |
      SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, EventData.ProcessId AS PID, EventData.TargetFilename, EventData.Image
      FROM source(artifact="Windows.EventLogs.Evtx", source="Microsoft-Windows-Sysmon/Operational")
      WHERE System.EventID = 11 AND EventData.TargetFilename =~ "(?i)\.(zip|rar|7z|gz|bz2|tar)$"', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1547.004', 'Boot or Logon Autostart Execution: Winlogon Helper DLL', NULL, 'High', NULL, 301, 'Collect Sysmon logs focusing on EventCode=1 (Process Creation) and EventCode=7 (Image/DLL Load) from WinEventLog:Sysmon channel. Gather Windows Security event logs for registry modification events. Extract SOFTWARE and NTUSER.DAT registry hives for offline analysis of Winlogon keys (Shell, Userinit, Notify subkeys). Use Autoruns registry scan data to enumerate all Winlogon autostart entries. Collect system timeline data including MFT and USN journal entries to correlate file system changes with registry modifications.', '1. Query Winlogon registry keys: ''reg query "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon" /v Shell'' and ''/v Userinit'' to check for unauthorized modifications or additional executables.
2. Check Notify subkey for malicious DLLs: ''reg query "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon\Notify"'' - this key should typically be empty or contain only known system notifications.
3. Monitor live Sysmon events for Winlogon-related process creation (EventID 1) and image loads (EventID 7): ''Get-WinEvent -FilterHashtable @{LogName="Microsoft-Windows-Sysmon/Operational"; ID=1,7} | Where-Object {$_.Message -match "winlogon|userinit"}''.
4. Verify current running processes spawned by winlogon.exe using ''wmic process get Name,ParentProcessId,ProcessId,CommandLine | findstr winlogon'' to identify suspicious child processes.
5. Use Autoruns or similar tools to enumerate all Winlogon autostart entries and validate digital signatures of referenced binaries.', '1. Extract and parse SOFTWARE registry hive, examining ''HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'' keys for Shell, Userinit, and Notify values - look for comma-separated executables in Userinit or non-standard Shell values.
2. Check NTUSER.DAT hives for user-specific Winlogon modifications at ''HKCU\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'' which could indicate per-user persistence.
3. Parse Windows Security event logs for registry modification events (EventID 4657) targeting Winlogon registry paths, correlating timestamps with system changes.
4. Analyze Sysmon logs for EventID 7 (Image/DLL Load) events where the Image is winlogon.exe or userinit.exe, identifying loaded modules and their file paths for validation.
5. Cross-reference MFT entries and file system timeline for creation/modification times of suspicious binaries referenced in Winlogon registry values.
6. Examine process creation logs (Sysmon EventID 1) for unusual parent-child relationships involving winlogon.exe spawning non-standard processes.', 'SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessImage, EventData.ImageLoaded AS LoadedDLL, EventData.ProcessId AS PID FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 7 AND (EventData.Image =~ "winlogon.exe" OR EventData.Image =~ "userinit.exe") AND NOT EventData.ImageLoaded =~ "(?i)C:\\\\Windows\\\\System32"', 'name: Windows.Detection.WinlogonHelperDLL
description: |
  Detects potential abuse of Winlogon Helper DLL technique by monitoring
  registry modifications and associated process/DLL loading events.
sources:
  - name: WinlogonRegistryKeys
    query: |
      SELECT Key.OSPath.Path AS RegistryPath, Key.OSPath.Components[-1] AS ValueName, 
             Data.value AS RegistryValue, Key.ModTime AS LastModified
      FROM glob(globs="HKEY_LOCAL_MACHINE/SOFTWARE/Microsoft/Windows NT/CurrentVersion/Winlogon/*", accessor="registry")
      WHERE ValueName IN ("Shell", "Userinit") OR RegistryPath =~ "Notify"
  - name: WinlogonProcessEvents
    query: |
      SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image AS ProcessImage,
             EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage
      FROM source(artifact="Windows.EventLogs.Evtx", source="Microsoft-Windows-Sysmon/Operational")
      WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ "winlogon.exe"
  - name: WinlogonDLLLoads
    query: |
      SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image AS ProcessImage,
             EventData.ImageLoaded AS LoadedDLL, EventData.Signed AS IsSigned
      FROM source(artifact="Windows.EventLogs.Evtx", source="Microsoft-Windows-Sysmon/Operational")
      WHERE System.EventID.Value = 7 AND EventData.Image =~ "winlogon.exe"', '2026-06-10 12:41:37.243319');
