INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1483', 'DGA', 'Windows/Linux', 'Medium', 'Review system artifacts.', 636, 'Standard Triage', 'Identify high-volume NXDOMAIN.', 'Analyze DNS request entropy.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1003.002', 'OS Credential Dumping: Security Account Manager', NULL, 'High', NULL, 7, 'Collect WinEventLog:Security EventCode=4688 for process creation showing registry dump commands. Collect WinEventLog:Sysmon EventCode=13,14 for registry access to SAM/SYSTEM hives. Collect WinEventLog:Sysmon EventCode=11 for file creation of dump files. Collect WinEventLog:Sysmon EventCode=2 for file system access to config directory. Target registry paths: HKLM\SAM\SAM\Domains\Account\Users, HKLM\SYSTEM\CurrentControlSet\Control\LSA. File paths: C:\Windows\System32\config\SAM, C:\Windows\System32\config\SYSTEM, and any .save/.dmp files in temp directories or user profiles.', '1. Monitor Windows Security Event Log for process creation events (EventID 4688) showing ''reg.exe save HKLM\sam'' or ''reg.exe save HKLM\system'' commands with SYSTEM privileges. 2. Check Sysmon Event ID 13/14 for registry access to HKLM\SAM\SAM\Domains\Account\Users or HKLM\SYSTEM keys by non-system processes. 3. Look for Sysmon Event ID 11 file creation events showing .save, .dmp, or suspicious files in temp directories following registry access. 4. Examine running processes for known credential dumping tools (pwdumpx.exe, gsecdump, mimikatz.exe) or PowerShell with suspicious registry access patterns. 5. Check for Volume Shadow Copy creation commands (vssadmin create shadow) used to bypass SAM file locks. 6. Monitor Sysmon Event ID 2 for file system access to C:\Windows\System32\config\SAM or SYSTEM files directly.', '1. Parse Windows Security Event Logs (Security.evtx) for EventID 4688 process creation showing ''reg save'' commands targeting SAM/SYSTEM hives, correlating timestamps with file creation. 2. Examine Sysmon logs (Microsoft-Windows-Sysmon%4Operational.evtx) for EventID 13/14 registry modifications and EventID 11 file creation of .save/.dmp files in suspicious locations. 3. Analyze MFT entries and file system timestamps for SAM database copies in temp directories, user profiles, or external media with timeline analysis. 4. Extract and examine actual SAM/SYSTEM registry hives from C:\Windows\System32\config\ checking LastWrite times on SAM\SAM\Domains\Account\Users keys. 5. Use tools like Impacket-secretsdump or samdump2 on recovered registry hives to verify if credential extraction occurred. 6. Check for remnants of credential dumping tools in prefetch files, recent documents, or browser downloads.', 'LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ ''(?i)reg\s+save\s+hklm\\(sam|system)'' OR EventData.CommandLine =~ ''(?i)vssadmin\s+create\s+shadow'' OR EventData.Image =~ ''(?i)(pwdumpx|gsecdump|mimikatz)\.exe'') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ ''(?i)reg\s+save\s+hklm\\(sam|system)'' OR EventData.CommandLine =~ ''(?i)vssadmin\s+create\s+shadow'' OR EventData.NewProcessName =~ ''(?i)(pwdumpx|gsecdump|mimikatz)\.exe'') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})', 'name: Custom.SAM.CredentialDumping
description: Detects SAM credential dumping via registry access and file creation
sources:
  - name: RegistryDumping
    query: |
      SELECT EventTime, Computer, EventData.ProcessName as ProcessName, EventData.CommandLine as CommandLine FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE EventID = 4688 AND CommandLine =~ ''(?i)reg\s+save\s+hklm\\(sam|system)''
  - name: RegistryAccess
    query: |
      SELECT EventTime, Computer, EventData.ProcessName as ProcessName, EventData.TargetObject as RegistryPath FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE EventID IN (13,14) AND TargetObject =~ ''(?i)HKLM\\SAM\\SAM\\Domains\\Account|HKLM\\SYSTEM''
  - name: DumpFileCreation
    query: |
      SELECT EventTime, Computer, EventData.ProcessName as ProcessName, EventData.TargetFilename as FilePath FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE EventID = 11 AND (TargetFilename =~ ''(?i)\.(save|dmp)$'' OR TargetFilename =~ ''(?i)(sam|system)\.(hiv|reg|bak)$'')', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1664', 'Network Management Discovery', NULL, 'Medium', NULL, 487, 'Cloud management logs and network flow data.', 'Detect API calls such as ''DescribeVpcs'', ''DescribeSubnets'', or ''GetRouteTable'' used to map cloud networking architecture.', 'Analyze IAM policy logs for identities that have been granted broad network ''Read'' permissions recently.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1672', 'Steal or Forge Cloud Authentication Credentials', NULL, 'Critical', NULL, 494, 'Global cloud audit logs and IAM configuration snapshots.', 'Monitor for ''AssumeRoleWithSAML'' or ''AssumeRoleWithWebIdentity'' from unauthorized IP addresses.', 'Inspect cloud configuration for unauthorized ''Identity Providers'' (IdP) added to the trust relationship.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1583.003', 'Acquire Infrastructure: Virtual Private Server', NULL, 'High', NULL, 394, 'Collect network flow data and connection logs from firewalls, routers, and endpoint agents. Gather DNS query logs from DNS servers and Windows DNS Client logs (Event ID 3008, 3020). Collect browser history and cache files from all user profiles. Preserve Windows Event Logs focusing on Security (4624, 4625, 4648), System, and Application logs. Capture registry hives including NTUSER.DAT, SOFTWARE, and SYSTEM. Collect network configuration files, SSH keys from .ssh directories, and VPN profiles. Gather process execution artifacts including prefetch files, UserAssist, and RecentApps registry keys.', '1. Monitor active network connections using netstat -an or PowerShell Get-NetTCPConnection to identify persistent outbound connections to suspicious IP ranges. 2. Check DNS resolution logs in Windows Event Log (Microsoft-Windows-DNS-Client/Operational) for queries to known VPS providers or bulletproof hosting domains. 3. Analyze running processes with Get-Process and their network activity using Get-NetTCPConnection -OwningProcess to correlate network activity with specific executables. 4. Review browser history and cached DNS entries for evidence of VPS provider websites or control panels being accessed. 5. Examine scheduled tasks and services for persistence mechanisms that maintain connections to external VPS infrastructure.', '1. Parse Windows Event Logs (System.evtx, Security.evtx) for logon events (4624, 4625) and network service starts that correlate with external connections. 2. Analyze browser artifacts including history databases, cache files, and saved credentials for VPS provider portals or control interfaces. 3. Examine MFT entries and file system timestamps for recently created configuration files, SSH keys, or VPN profiles that enable VPS access. 4. Review registry entries in HKEY_CURRENT_USER\Software and HKEY_LOCAL_MACHINE\Software for stored connection profiles, API keys, or cloud service configurations. 5. Parse network configuration files, hosts files, and DNS cache entries for hardcoded VPS IP addresses or domains. 6. Analyze prefetch files and UserAssist registry keys for execution of remote administration tools or cloud management utilities.', 'SELECT timestamp(epoch=System.TimeCreated.SystemTime) as EventTime, EventData.IpAddress as RemoteIP, EventData.IpPort as RemotePort, EventData.ProcessName as Process, EventData.ProcessId as PID FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE System.EventID.Value = 5156 AND EventData.Direction = ''Outbound'' AND NOT EventData.IpAddress =~ ''(?i)10.'' AND NOT EventData.IpAddress =~ ''(?i)192.168.'' AND NOT EventData.IpAddress =~ ''(?i)172.''', 'name: VPS_Infrastructure_Detection
description: Detect connections and artifacts related to VPS acquisition and usage
imports:
  - Windows.Forensics.Chrome
sources:
  - name: Network_Connections
    query: |
      SELECT System.TimeCreated.SystemTime as EventTime, EventData.IpAddress as RemoteIP, EventData.ProcessName as Process
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE System.EventID.Value = 5156 AND EventData.Direction = ''Outbound''
  - name: DNS_Queries
    query: |
      SELECT System.TimeCreated.SystemTime as EventTime, EventData.QueryName as Domain, EventData.QueryType as Type
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx'')
      WHERE System.EventID.Value = 3008 AND (EventData.QueryName =~ ''(?i)(vultr|digitalocean|linode|aws|azure|ovh)''
  - name: Browser_History
    query: |
      SELECT Timestamp, URL, Title, VisitCount
      FROM glob(globs=''C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History'')
      WHERE URL =~ ''(?i)(vps|hosting|cloud|server|infrastructure)''', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1593.001', 'Social Media', 'Cross-Platform', 'Low', 'Perform baseline triage.', 782, 'Collect proxy logs and web filtering logs showing social media site access patterns. Gather DNS query logs from network infrastructure. Preserve browser artifacts including history databases, cache files, and cookie stores from user workstations. Collect network flow data and firewall logs for connections to social media platforms and APIs. Obtain email server logs and security tool alerts for potential follow-up reconnaissance or social engineering attempts. Note: Most social media reconnaissance occurs outside organizational visibility.', '1. Review network connection logs and proxy logs for connections to social media platforms during reconnaissance timeframes. 2. Examine browser history and cache files on user workstations for evidence of social media reconnaissance activity. 3. Check DNS query logs for lookups to social media domains and associated CDN/API endpoints. 4. Analyze email logs and web application firewall logs for potential follow-up activities like spearphishing attempts. 5. Review user account creation logs and authentication events for suspicious new accounts that may have been established based on gathered intelligence.', '1. Extract and analyze browser artifacts (history, cache, downloads) from %USERPROFILE%\AppData\Local\* browser folders for social media site visits. 2. Parse MFT entries for recently created or modified files that may contain harvested social media data or reconnaissance notes. 3. Examine deleted files and unallocated space for cached social media content, screenshots, or harvested profile information. 4. Analyze application data folders and temporary directories for tools used in social media reconnaissance or OSINT gathering. 5. Review file system timestamps and access patterns to establish timeline of reconnaissance activities.', 'SELECT timestamp(epoch=System.TimeCreated.SystemTime), EventData.ProcessName, EventData.CommandLine, EventData.Image FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ ''(?i)(facebook|twitter|linkedin|instagram|github)'' OR EventData.Image =~ ''(?i)(chrome|firefox|edge|curl|wget|python)'')', 'name: T1593001_SocialMediaReconnaissance
description: Detect potential social media reconnaissance activities
imports:
  - Windows.EventLogs.Sysmon
  - Windows.Forensics.Chrome.History
  - Windows.Linux.Network.Netstat
sources:
  - name: WebBrowserHistory
    query: |
            SELECT Timestamp, URL, Title, VisitCount FROM glob(globs=''C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History'') WHERE URL =~ ''(?i)(facebook|twitter|linkedin|instagram|github|social)''
        - name: NetworkConnections
          query: |
            SELECT Timestamp, local_address, remote_address, remote_port FROM glob(globs=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE remote_address =~ ''(?i)(facebook|twitter|linkedin|instagram)''
        - name: ProcessExecution
          query: |
            SELECT Timestamp, Image, CommandLine FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE EventID = 1 AND CommandLine =~ ''(?i)(osint|social|recon|harvester)''', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1593.002', 'Search Engines', 'Cross-Platform', 'Low', 'Perform baseline triage.', 734, 'Browser history databases from all user profiles, proxy server logs, DNS query logs, web server access logs showing search engine crawler activity, network packet captures containing HTTP/HTTPS traffic to search engines, browser cache and temporary internet files, downloaded files from search results. Focus on external-facing systems and perimeter monitoring as this activity typically occurs outside organizational visibility.', '1. Check browser history databases for search engine queries targeting the organization (Chrome: %LOCALAPPDATA%\Google\Chrome\User Data\Default\History, Firefox: %APPDATA%\Mozilla\Firefox\Profiles\*.default\places.sqlite). 2. Review proxy logs for search engine traffic patterns and suspicious query parameters. 3. Examine network traffic logs for connections to search engines with organization-related query strings in URLs. 4. Check DNS logs for repeated queries to search engine domains from internal systems. 5. Review web server access logs for search engine crawler activity and potential information leakage through indexed content.', '1. Extract and parse browser history SQLite databases from user profiles to identify reconnaissance-related search queries. 2. Analyze browser cache files for stored search engine results pages containing organization information. 3. Extract browser artifacts using tools like hindsight or BrowsingHistoryView to timeline search activities. 4. Parse proxy log files and web traffic captures for search engine queries with suspicious parameters. 5. Examine downloaded files and documents that may have been discovered through search engine reconnaissance.', 'SELECT FullPath FROM glob(globs=''C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History'')', 'name: Custom.Reconnaissance.SearchEngines
description: Detect search engine reconnaissance activities across browsers
sources:
  - name: ChromeSearchHistory
    query: |
            SELECT Timestamp, ''Chrome'' AS Browser, Profile, URL, Title, VisitCount
            FROM glob(globs=''C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History'')
            WHERE URL =~ ''(?i)(google\.com|bing\.com|yahoo\.com|duckduckgo\.com).*[?&]q=''
            AND (URL =~ ''(?i)site:'' OR URL =~ ''(?i)filetype:'' OR URL =~ ''(?i)inurl:'' OR URL =~ ''(?i)intitle:'')
        - name: FirefoxSearchHistory
          query: |
            SELECT Timestamp, ''Firefox'' AS Browser, Profile, URL, Title, VisitCount
            FROM source(artifact=''Windows.Forensics.Firefox'')
            WHERE URL =~ ''(?i)(google\.com|bing\.com|yahoo\.com|duckduckgo\.com).*[?&]q=''
            AND (URL =~ ''(?i)site:'' OR URL =~ ''(?i)filetype:'' OR URL =~ ''(?i)inurl:'' OR URL =~ ''(?i)intitle:'')
        - name: EdgeSearchHistory
          query: |
            SELECT Timestamp, ''Edge'' AS Browser, Profile, URL, Title, VisitCount
            FROM source(artifact=''Windows.Forensics.Edge'')
            WHERE URL =~ ''(?i)(google\.com|bing\.com|yahoo\.com|duckduckgo\.com).*[?&]q=''
            AND (URL =~ ''(?i)site:'' OR URL =~ ''(?i)filetype:'' OR URL =~ ''(?i)inurl:'' OR URL =~ ''(?i)intitle:'')
', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1487', 'Disk Structure Wipe', 'Windows/Linux', 'Medium', 'Review system artifacts.', 637, 'Standard Triage', 'Monitor for MBR/VBR overwrites.', 'Analyze physical drive writes.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1527', 'Application Access Token', 'Cross-Platform', 'Low', 'Perform baseline triage.', 681, 'General Collection', 'Review logs for execution.', 'Search disk for file modifications.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1021.006', 'Remote Services: WinRM', NULL, 'High', NULL, 30, 'Collect WinEventLog:Security (EventCode=4624,4648) for authentication events, WinEventLog:Sysmon (EventCode=1) for process creation, WinEventLog:WinRM operational logs (EventCode=6) for session tracking, PowerShell operational logs (EventCode=4103,4104) for command execution correlation, network connection logs focusing on inbound connections to ports 5985/5986, registry keys under HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\WSMAN and user hives for WinRM configuration, and file system artifacts including wsmprovhost.exe execution traces and temporary files created during remote sessions.', '1. Check WinRM service status and configuration: ''Get-Service WinRM'' and ''winrm get winrm/config/Service'' to verify if AllowRemoteAccess is enabled. 2. Monitor active WinRM processes: ''Get-Process wsmprovhost'' and examine parent/child relationships with ''Get-CimInstance Win32_Process | Where-Object {$_.Name -eq "wsmprovhost.exe"} | Select-Object ProcessId,ParentProcessId,CommandLine''. 3. Check current WinRM sessions: ''Get-PSSession'' and ''winrm enumerate winrm/config/listener'' to identify active remote sessions. 4. Review recent Security event logs: ''Get-WinEvent -LogName Security | Where-Object {$_.Id -in @(4624,4648)} | Select-Object -First 50'' focusing on Type 3 (Network) and Type 10 (RemoteInteractive) logons. 5. Examine WinRM operational logs: ''Get-WinEvent -LogName Microsoft-Windows-WinRM/Operational | Where-Object {$_.Id -eq 6}'' for session creation events. 6. Check for suspicious PowerShell activity: ''Get-WinEvent -LogName Microsoft-Windows-PowerShell/Operational | Where-Object {$_.Id -eq 4103}'' to correlate with WinRM sessions.', '1. Parse Security.evtx for Event IDs 4624 (successful logons) and 4648 (explicit credential use), filtering for LogonType 3 (Network) from remote IP addresses on ports 5985/5986. 2. Examine Microsoft-Windows-WinRM-Operational.evtx for Event ID 6 (WSMan session creation), Event ID 91 (session initialization), and Event ID 169 (user authentication events). 3. Correlate WinRM session IDs from operational logs with PowerShell Script Block logs (Event ID 4104) in Microsoft-Windows-PowerShell-Operational.evtx to identify executed commands. 4. Parse Sysmon logs (Event ID 1) for wsmprovhost.exe process creation events and analyze parent-child process relationships. 5. Check NTUSER.DAT registry hives for WinRM client configuration under ''SOFTWARE\Microsoft\Windows\CurrentVersion\WSMAN''. 6. Analyze network connection logs and correlate timestamps between authentication events, WinRM sessions, and process creation within defined time windows (typically 60 seconds).', 'SELECT EventTime, Computer, EventData, Message FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/System.evtx'') WHERE System.EventID.Value = 6 AND EventTime > timestamp(epoch=now() - 86400)', 'name: Windows.Detection.WinRM.LateralMovement
description: Detect WinRM lateral movement by correlating authentication, session creation, and process execution
sources:
  - name: WinRM_Sessions
    query: |
      SELECT System.TimeCreated.SystemTime, System.Computer, EventData.User as User, EventData.ClientIP as SourceIP, System.EventRecordID as RecordID
      FROM parse_evtx(filename=expand(path=''%SystemRoot%/System32/winevt/logs/Microsoft-Windows-WinRM-Operational.evtx''))
      WHERE System.EventID.Value = 6 AND System.TimeCreated.SystemTime > timestamp(epoch=now() - 86400)
  - name: Authentication_Events
    query: |
      SELECT System.TimeCreated.SystemTime, System.Computer, EventData.LogonType as LogonType, EventData.IpAddress as SourceIP, EventData.TargetUserName as User
      FROM parse_evtx(filename=expand(path=''%SystemRoot%/System32/winevt/logs/Security.evtx''))
      WHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType IN (''3'', ''10'') AND System.TimeCreated.SystemTime > timestamp(epoch=now() - 86400)
  - name: Process_Creation
    query: |
      SELECT System.TimeCreated.SystemTime, System.Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.User
      FROM parse_evtx(filename=expand(path=''%SystemRoot%/System32/winevt/logs/Microsoft-Windows-Sysmon-Operational.evtx''))
      WHERE System.EventID.Value = 1 AND EventData.Image =~ ''wsmprovhost.exe'' AND System.TimeCreated.SystemTime > timestamp(epoch=now() - 86400)', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1022', 'Data Encrypted for Exfiltration', NULL, 'Low', NULL, 503, 'Prefetch, Amcache, and File System Metadata ($MFT) to identify the creation of encrypted archives.', '1. Look for high-entropy (heavily encrypted/compressed) files in staging areas like C:\Windows\Temp or C:\Users\Public.
2. Monitor for execution of archiving tools (7z.exe, rar.exe, zip.exe) with command-line arguments involving ''-p'' (password) or encryption flags.', '1. Search the $MFT for files with extensions like .7z, .rar, or .zip created shortly before high network egress timestamps.
2. Use ''Prefetch'' or ''Amcache'' to determine if encryption utilities were run by the attacker to prepare data for exfiltration.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1041', 'Exfiltration Over C2 Channel', NULL, 'Critical', NULL, 67, 'Collect Sysmon logs (Microsoft-Windows-Sysmon/Operational) focusing on Event ID 1 (Process Creation), Event ID 3 (Network Connection), and Event ID 22 (DNS Query). Gather Windows Security logs (Security.evtx) for Event IDs 4663, 4670, 4656 (Object Access auditing). Obtain SRUDB.dat from C:\Windows\System32\sru\ for network usage statistics by process. Collect network flow data from NSM tools, firewall logs, and any available PCAP captures. For Linux systems, gather auditd logs focusing on execve and connect syscalls from /var/log/audit/audit.log. For macOS, collect Unified Logs using ''log show --predicate "eventMessage CONTAINS[c] open OR eventMessage CONTAINS[c] sendto OR eventMessage CONTAINS[c] connect"'' and osquery socket_events and process_events tables. Include ESXi vpxa logs, vmkernel network logs, and syslog entries for virtualized environments.', '1. Monitor active network connections using ''netstat -ano'' and cross-reference PIDs with suspicious processes. Look for connections with high bytes_sent ratios in ''Get-NetTCPConnection | Select-Object LocalAddress,RemoteAddress,State,OwningProcess''. 2. Capture Sysmon Event ID 3 (Network Connection) in real-time using ''Get-WinEvent -FilterHashtable @{LogName=''Microsoft-Windows-Sysmon/Operational''; ID=3}'' to identify C2 channels. 3. Use Performance Monitor or PowerShell to track process network utilization: ''Get-Counter "\Process(*)\IO Data Bytes/sec"'' for processes showing abnormal outbound traffic. 4. Monitor file access patterns with Sysmon Event ID 11 (File Created) followed immediately by network activity to detect data staging before exfiltration. 5. Check Windows Security Event ID 4663 (Object Access) for sensitive file reads that correlate with network spikes. 6. Use ''netsh trace start capture=yes tracefile=c:\capture.etl provider=Microsoft-Windows-TCPIP'' to capture detailed network flows for analysis.', '1. Parse SRUDB.dat (System Resource Usage Monitor) located at C:\Windows\System32\sru\SRUDB.dat to identify total bytes sent by suspicious processes over time using tools like srum_dump. 2. Extract and analyze Sysmon Event ID 3 (Network Connection) and Event ID 1 (Process Creation) from Microsoft-Windows-Sysmon/Operational.evtx to correlate process execution with network activity. 3. Examine Windows Security.evtx for Event IDs 4663, 4670, 4656 (Object Access) to identify sensitive file access patterns preceding network transmission. 4. Analyze network flow data from firewall logs, router logs, or captured PCAP files to identify high-volume outbound transfers over established C2 channels. 5. Review browser history, temporary files, and application logs in user profiles for evidence of data staging or encoding before transmission. 6. Parse MFT entries and USN Journal to identify recently accessed sensitive files that correlate with network transmission timestamps.', 'SELECT EventTime, Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 3 AND EventData.Initiated = ''true'' AND NOT (EventData.DestinationIp =~ ''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.)'' OR EventData.DestinationIp =~ ''^(169\.254\.|224\.|239\.|255\.)'') ORDER BY EventTime DESC', 'name: Custom.T1041.ExfiltrationOverC2
description: |
  Detects potential data exfiltration over C2 channels by correlating file access with network connections
  
sources:
  - name: SysmonNetworkConnections
    query: |
      SELECT EventTime, Computer, EventData.Image, EventData.ProcessId, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE System.EventID = 3 AND EventData.Initiated = ''true''
      
  - name: FileAccessEvents
    query: |
      SELECT EventTime, Computer, EventData.SubjectUserName, EventData.ObjectName, EventData.ProcessName, EventData.ProcessId
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE System.EventID IN (4663, 4656) AND EventData.ObjectName =~ ''(?i)\\(documents|desktop|downloads|users)\\.*\.(doc|pdf|xls|txt|zip)$''
      
  - name: NetworkUtilizationSRUM
    query: |
      SELECT * FROM source(artifact=''Windows.Forensics.SRUM'')
      WHERE BytesSent > 1048576', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1583.002', 'DNS Server', 'Windows/Linux', 'Medium', 'Review system artifacts.', 641, 'Collect Windows DNS Server event logs from Microsoft-Windows-DNS-Server-Service/Operational and Microsoft-Windows-DNS-Server-Service/Admin channels. Gather DNS service configuration from registry HKLM\SYSTEM\CurrentControlSet\Services\DNS and network interface settings from HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters. Collect DNS zone files and configuration from %SystemRoot%\System32\dns\ directory. Capture network configuration logs showing DNS resolver changes. For detection focus on related C2 stages, collect DNS query logs, network flow data showing DNS traffic patterns, and process execution logs for DNS server software installations.', '1. Check local DNS server configuration in Windows DNS Manager or via PowerShell Get-DnsServerSetting to identify any unauthorized DNS servers. 2. Review network adapter DNS settings using ipconfig /all or Get-DnsClientServerAddress to detect DNS server changes. 3. Examine running DNS services with Get-Service -Name DNS and check for unexpected DNS processes. 4. Monitor active network connections to port 53 using netstat -an | findstr :53 to identify DNS traffic patterns. 5. Check Windows Event Logs for DNS service events (Event ID 2 for DNS server start, Event ID 4013 for DNS zone loading) in DNS Server log.', '1. Extract DNS server configuration files from %SystemRoot%\System32\dns\ directory including zone files and boot configuration. 2. Parse Windows Event Logs focusing on DNS Server log channel for service start/stop events and zone modifications. 3. Analyze registry keys under HKLM\SYSTEM\CurrentControlSet\Services\DNS for DNS service configuration changes. 4. Review network adapter registry settings under HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces for DNS server assignments. 5. Examine MFT entries for timeline analysis of DNS-related file modifications in system DNS directories. 6. Parse application logs for third-party DNS software installations or configurations.', 'SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, System.EventID.Value as EventID, System.Computer as Computer, EventData.Data as EventData FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/System.evtx'') WHERE System.EventID.Value IN (2, 4013, 6527) OR EventData.Data =~ ''DNS.*[Ss]erver.*[Ss]tart''', 'name: Custom.T1583.002.DNSServer
description: Detect DNS server acquisition and configuration changes
sources:
  - name: DNSServerEvents
    query: |
      SELECT System.TimeCreated.SystemTime as Timestamp, System.EventID as EventID, System.Computer as Computer, EventData.Data as EventData FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE System.EventID IN (2, 4013, 6527, 770)
  - name: DNSRegistryConfig
    query: |
      SELECT FullPath, Name, Data.value as Value, Data.type as Type FROM source(artifact=''Windows.Registry.Glob'', globs=''HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Services/DNS/**'') WHERE Name =~ ''(ServerLevelPluginDll|ForwardDelegations|Forwarders)''
  - name: NetworkDNSConfig
    query: |
      SELECT FullPath, Name, Data.value as DNSServers FROM source(artifact=''Windows.Registry.Glob'', globs=''HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Services/Tcpip/Parameters/Interfaces/*/NameServer'')', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1059.007', 'Command and Scripting Interpreter: JavaScript/JScript', NULL, 'High', NULL, 97, 'Collect Sysmon Event ID 1 (process creation) and Event ID 7 (image loaded) from Microsoft-Windows-Sysmon/Operational channel focusing on wscript.exe, cscript.exe, mshta.exe, node.exe processes. Gather PowerShell ScriptBlock logging Event ID 4104 and AMSI events from Microsoft-Windows-PowerShell/Operational. For Linux, collect auditd SYSCALL execve events targeting node and JavaScript interpreters. On macOS, gather unified logs with predicate ''eventMessage CONTAINS "osascript"'' and process_events via osquery. Collect all .js, .jse, .hta, .scr files from user profiles, temp directories, and download folders. Capture network connection logs correlating with JavaScript execution timeframes.', '1. Check for JavaScript interpreters in process list: Get-Process wscript,cscript,mshta,node,osascript and examine command-line arguments for .js/.jse files or suspicious paths. 2. Query Sysmon Event ID 1 for recent JavaScript execution: Get-WinEvent -FilterHashtable @{LogName=''Microsoft-Windows-Sysmon/Operational'';ID=1} | Where-Object {$_.Message -match ''wscript|cscript|mshta|osascript''}. 3. Monitor PowerShell ScriptBlock logging (Event ID 4104) for AMSI detections of obfuscated JavaScript content. 4. Examine active network connections from JavaScript processes: netstat -ano | findstr PID and correlate with process execution times. 5. Check Windows Script Host registry settings at HKLM\SOFTWARE\Microsoft\Windows Script Host\Settings for policy bypasses or modifications.', '1. Parse Sysmon Event ID 1 logs for wscript.exe, cscript.exe, mshta.exe execution with focus on ParentProcessName (Office apps, browsers) and CommandLine containing .js/.jse files. 2. Examine file system artifacts in %TEMP%, %APPDATA%, Downloads folders for .js, .jse, .hta files with recent timestamps and high entropy content. 3. Analyze browser cache and temporary internet files for downloaded JavaScript payloads, correlating with network activity logs. 4. Review Windows Event Log Security 4688 (process creation) for JavaScript interpreter launches with TokenElevationType indicating privilege escalation attempts. 5. Parse MFT entries for recently created/modified .js files in user directories and system paths, noting file size and creation patterns. 6. On macOS systems, examine /var/log/system.log for osascript execution and check ~/Library/Scripts for JXA artifacts.', 'SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.ProcessId as ProcessId, EventData.Image as ProcessImage, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage, EventData.ParentCommandLine as ParentCommandLine FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 1 AND (EventData.Image =~ ''(?i)(wscript|cscript|mshta|node)\.exe$'' OR EventData.CommandLine =~ ''(?i)\.(js|jse|hta)\b'') AND EventData.ParentImage =~ ''(?i)(excel|winword|outlook|chrome|firefox|iexplore)\.exe$''', 'name: Custom.JavaScript.Execution.Hunt
description: Detect JavaScript execution via multiple interpreters across file system and process artifacts
sources:
- name: JavaScriptProcessExecution
  query: |
        SELECT System.TimeCreated.SystemTime as EventTime,
               EventData.ProcessId as ProcessId,
               EventData.Image as ProcessImage,
               EventData.CommandLine as CommandLine,
               EventData.ParentImage as ParentImage
        FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
        WHERE System.EventID.Value = 1
        AND EventData.Image =~ ''(?i)(wscript|cscript|mshta|node)\.exe$''
        AND (EventData.CommandLine =~ ''(?i)\.(js|jse|hta)\b'' OR EventData.ParentImage =~ ''(?i)(excel|winword|outlook|chrome|firefox)\.exe$'')

- name: JavaScriptFileArtifacts
  query: |
    SELECT FullPath, Size, Mtime, Ctime, hash(path=FullPath, hashselect=''SHA256'') as SHA256
    FROM glob(globs=''C:/Users/*/Downloads/*'', ''C:/Windows/Temp/*'')$'')
    WHERE FullPath =~ ''(?i)(temp|download|appdata|users)'' AND Mtime > now() - 86400
    LIMIT 1000', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1009', 'Binary Padding', 'Windows/Linux', 'Medium', 'Review system artifacts.', 530, 'Standard Triage', 'Check for unusual file sizes/bloat.', 'Analyze PE overlays for null-byte padding.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1013', 'Port Monitors', 'Windows/Linux', 'Medium', 'Review system artifacts.', 532, 'Standard Triage', 'Check HKLM\SYSTEM\...\Print\Monitors.', 'Analyze SYSTEM hive for Print Monitor persistence.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1015', 'Accessibility Features', 'Windows/Linux', 'Medium', 'Review system artifacts.', 533, 'Standard Triage', 'Check sethc.exe/utilman.exe ''Debugger'' keys.', 'Analyze IFEO keys in Software hive.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1017', 'Application Deployment Software', 'Windows/Linux', 'Medium', 'Review system artifacts.', 534, 'Standard Triage', 'Audit SCCM/Intune deployment logs.', 'Parse CCM logs in C:\Windows\CCM\Logs.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1090.001', 'Proxy: Internal Proxy', NULL, 'High', NULL, 136, 'Collect Sysmon logs (Event ID 1, 3, 22) from WinEventLog:Sysmon channel for process creation and network connections. Gather Windows Firewall logs focusing on SMB traffic over non-standard ports. Collect SYSTEM registry hive for PortProxy service configurations. For Linux systems, collect auditd logs (SYSCALL execve events) and NSM connection logs. Obtain ESXi shell logs from /var/log/shell.log and vmkernel logs from /var/log/vmkernel.log. For network devices, collect firewall audit logs showing configuration changes and CLI command logs for policy updates. Include NSM flow data (conn.log) for internal traffic analysis across all platforms.', '1. Monitor active network connections for internal proxy activity using ''netstat -ano'' and correlate PIDs with running processes to identify unexpected internal connections. 2. Check Windows Event Logs for Sysmon Event ID 3 (Network Connection) focusing on processes like rundll32.exe, svchost.exe, or cmd.exe making connections to internal hosts on unusual ports (1080, 8080, 4444). 3. Execute ''netsh interface portproxy show all'' to identify any configured port forwarding rules that could facilitate internal proxying. 4. Use ''wmic process list full'' to identify suspicious processes with command lines containing proxy tools like HTRAN, socat, or netsh portproxy commands. 5. Monitor real-time SMB traffic over non-standard ports using ''netstat -an | findstr :445'' and check for SMB connections on high ports. 6. Review running services with ''sc query'' and ''tasklist /svc'' to identify any unauthorized proxy services or processes binding to listening ports.', '1. Parse Windows Event Logs (System.evtx, Security.evtx) for Sysmon Event ID 1 (Process Creation) with command lines containing ''netsh interface portproxy'', ''socat'', or other tunneling tools. 2. Examine SYSTEM registry hive at ''HKLM\SYSTEM\CurrentControlSet\Services\PortProxy\v4tov4'' and ''v6tov4'' keys for persistent port forwarding configurations. 3. Analyze Sysmon Event ID 3 logs for network connections between internal hosts, focusing on workstation-to-workstation communications using SMB, RPC, or high ports (>1024). 4. Review UserAssist registry entries (NTUSER.DAT) at ''Software\Microsoft\Windows\CurrentVersion\Explorer\UserAssist'' for execution of proxy tools like chisel.exe, htran.exe, or custom tunneling utilities. 5. Parse MFT records for recently created or modified files in temp directories with names matching known proxy tools or suspicious executables. 6. Examine Windows Firewall logs for internal traffic patterns showing unusual east-west communication flows between endpoints.', 'SELECT timestamp(epoch=System.TimeCreated.SystemTime), Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.Protocol, EventData.SourceIp as SrcIP FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 3 AND EventData.Image =~ ''(rundll32|svchost|cmd|powershell)\.exe$'' AND EventData.DestinationIp =~ ''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)'' AND EventData.DestinationPort IN (''1080'', ''8080'', ''4444'', ''3389'', ''22'') ORDER BY Timestamp DESC', 'name: Windows.Detection.InternalProxy
description: Detect internal proxy activity through process execution and network connections
sources:
  - name: ProxyProcessExecution
    query: |
      SELECT Timestamp, Computer, EventData.Image, EventData.CommandLine, EventData.ProcessId
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'')
      WHERE System.EventID = 1 AND EventData.CommandLine =~ ''(netsh.*portproxy|socat|htran|chisel|proxychains)''
  - name: SuspiciousInternalConnections
    query: |
      SELECT Timestamp, Computer, EventData.Image, EventData.SourceIp, EventData.DestinationIp, EventData.DestinationPort
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') 
      WHERE System.EventID = 3 AND EventData.DestinationIp =~ ''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)'' AND EventData.DestinationPort IN (''1080'', ''8080'', ''4444'', ''9999'')
  - name: PortProxyRegistry
    query: |
      SELECT FullPath, Data.value as ProxyConfig FROM source(artifact=''Windows.Registry.Glob'')
      WHERE KeyGlob = ''HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Services/PortProxy/**'' AND Data', '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1127', 'Trusted Developer Utilities Proxy Execution', NULL, 'High', NULL, 173, 'Collect Windows Security Event Log (EventCode=4688 process creation), Sysmon logs (EventCode=1 process creation, EventCode=3 network connections, EventCode=7 image loads, EventCode=11 file creation, EventCode=22 DNS queries), AppLocker logs for audit/block events of developer utilities. Gather Prefetch files for MSBuild.exe, csc.exe, dnx.exe, rcsi.exe, windbg.exe. Collect any .xml, .csproj, .csx, .dgml project files referenced in developer utility command lines. Include PowerShell operational logs (EventCode=4103, 4104) for script block logging when developer utilities spawn PowerShell. Collect network flow data correlating with developer utility process IDs and timestamps.', '1. Check for developer utilities in unexpected locations using ''Get-Process | Where-Object {$_.ProcessName -match "MSBuild|csc|dnx|rcsi|windbg|devenv"} | Select-Object ProcessName,Path,CommandLine,ParentProcessId''. 2. Monitor Sysmon Event ID 1 in real-time for developer utilities spawning suspicious children: ''Get-WinEvent -FilterHashtable @{LogName=''Microsoft-Windows-Sysmon/Operational''; ID=1} | Where-Object {$_.Message -match ''MSBuild|csc.exe|dnx.exe'' -and $_.Message -match ''powershell|cmd.exe|rundll32|regsvr32|wscript''}''. 3. Check for network connections from developer utilities using ''netstat -anob | findstr MSBuild'' and correlate with Sysmon Event ID 3. 4. Examine running processes for unsigned DLL loads by developer utilities via Sysmon Event ID 7. 5. Look for recent file writes to user-writable paths by these utilities using ''Get-WinEvent -FilterHashtable @{LogName=''Microsoft-Windows-Sysmon/Operational''; ID=11}'' and filter for temp/appdata locations.', '1. Parse Security Event Log 4688 entries for developer utility process creation events, focusing on command lines containing .xml, .csproj, or script files in suspicious locations like %TEMP% or %APPDATA%. 2. Analyze Sysmon Event ID 1 logs for MSBuild.exe, csc.exe, dnx.exe executions with unusual parent processes or command line arguments referencing user-writable directories. 3. Examine Sysmon Event ID 11 (File Create) for developer utilities writing PE files to suspicious locations, correlating timestamps with network activity. 4. Review Prefetch files for MSBuild.exe, csc.exe, and other developer utilities to establish execution timeline and frequency patterns. 5. Parse Sysmon Event ID 7 (Image Load) for developer utilities loading unsigned or user-writable DLLs. 6. Analyze any .xml, .csproj, .csx, or .dgml files referenced in command lines for embedded malicious code or download cradles.', 'LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 1 AND ((EventData.Image =~ ''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe|rcsi\.exe|windbg\.exe)$'' AND EventData.CommandLine =~ ''(?i)\\(temp|appdata|public|programdata)'') OR (EventData.ParentImage =~ ''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe)$'' AND EventData.Image =~ ''(?i)(powershell\.exe|cmd\.exe|rundll32\.exe|regsvr32\.exe|wscript\.exe|mshta\.exe)$'')) LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE System.EventID.Value = 4688 AND ((EventData.NewProcessName =~ ''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe|rcsi\.exe|windbg\.exe)$'' AND EventData.CommandLine =~ ''(?i)\\(temp|appdata|public|programdata)'') OR (EventData.ParentProcessName =~ ''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe)$'' AND EventData.NewProcessName =~ ''(?i)(powershell\.exe|cmd\.exe|rundll32\.exe|regsvr32\.exe|wscript\.exe|mshta\.exe)$'')) SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})', 'name: Windows.Detection.T1127.TrustedDeveloperUtilities
description: Detects trusted developer utilities proxy execution across multiple log sources
sources:
  - name: DeveloperUtilityProcesses
    query: |
      SELECT System.TimeCreated.SystemTime AS EventTime,
             EventData.Image AS ProcessName,
             EventData.CommandLine,
             EventData.ParentImage,
             EventData.ProcessId
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID.Value = 1
        AND EventData.Image =~ ''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe|rcsi\.exe|windbg\.exe)$''
        AND (EventData.CommandLine =~ ''(?i)\\(temp|appdata|public|users\\\\public)''
             OR EventData.ParentImage =~ ''(?i)(explorer\.exe|winword\.exe|excel\.exe|outlook\.exe)'')

  - name: SuspiciousChildProcesses
    query: |
      SELECT System.TimeCreated.SystemTime AS EventTime,
             EventData.Image AS ChildProcess,
             EventData.ParentImage AS ParentProcess,
             EventData.CommandLine
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID.Value = 1
        AND EventData.ParentImage =~ ''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe|rcsi\.exe)$''
        AND EventData.Image =~ ''(?i)(powershell\.exe|cmd\.exe|rundll32\.exe|regsvr32\.exe|wscript\.exe|mshta\.exe)$''

  - name: NetworkConnections
    query: |
      SELECT System.TimeCreated.SystemTime AS EventTime,
             EventData.Image AS ProcessName,
             EventData.DestinationIp,
             EventData.DestinationPort,
             EventData.ProcessId
      FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'')
      WHERE System.EventID.Value = 3
        AND EventData.Image =~ ''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe)$''
        AND NOT EventData.DestinationIp =~ ''^(127\.|10\.|192\.168\.|172\.1[6-9]\.|172\.2[0-9]\.|172\.3[0-1]\.)''', '2026-06-10 12:41:37.243319');
