INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1506', 'Web Session Cookie', 'Cross-Platform', 'Low', 'Perform baseline triage.', 795, 'General Collection', 'Review logs for execution.', 'Search disk for file modifications.', NULL, NULL, '2026-06-10 12:41:37.243319');
INSERT INTO public.ref_artifact_library (t_code, name, os, priority, analysis_steps, id, collection_strategy, live_analysis, dead_disk_analysis, custom_vql, surgical_yaml, updated_at) VALUES ('T1547.002', 'Authentication Package', 'Cross-Platform', 'Low', 'Perform baseline triage.', 766, 'Collect Windows Security event log (WinEventLog:Security) focusing on Event ID 4657 for registry value modifications. Collect Sysmon operational log (WinEventLog:Microsoft-Windows-Sysmon/Operational) focusing on Event ID 7 for image/library loads. Acquire SYSTEM registry hive from Windows/System32/config/SYSTEM to examine LSA authentication package configurations. Collect any DLL files referenced in HKLM\SYSTEM\CurrentControlSet\Control\Lsa\Authentication Packages registry entries for signature validation and hash analysis. Include Windows boot logs and LSA operational logs if available for correlation of authentication package loading events.', '1. Check LSA registry key for unauthorized authentication packages: `reg query "HKLM\SYSTEM\CurrentControlSet\Control\Lsa" /v "Authentication Packages"` and compare against baseline. 2. Examine Security event log for registry modifications: `Get-WinEvent -FilterHashtable @{LogName=''Security''; ID=4657} | Where-Object {$_.Message -match ''Lsa.*Authentication''}` 3. Review Sysmon Event ID 7 for LSASS DLL loads: `Get-WinEvent -FilterHashtable @{LogName=''Microsoft-Windows-Sysmon/Operational''; ID=7} | Where-Object {$_.Message -match ''lsass.exe''}` 4. Identify unsigned or suspicious DLLs loaded by LSASS: `Get-Process lsass | Select-Object -ExpandProperty Modules | Where-Object {-not (Get-AuthenticodeSignature $_.FileName).Status -eq ''Valid''}` 5. Correlate registry modification timestamps with LSASS DLL load events within reasonable time windows (typically system boot cycles).', '1. Extract and parse SYSTEM registry hive from `Windows/System32/config/SYSTEM`, focusing on `CurrentControlSet\Control\Lsa\Authentication Packages` key for unauthorized entries. 2. Parse Security event logs (`Windows/System32/winevt/Logs/Security.evtx`) for Event ID 4657 registry modifications targeting LSA authentication package keys. 3. Analyze Sysmon logs (`Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx`) for Event ID 7 image loads by lsass.exe process. 4. Cross-reference MFT entries for DLL files referenced in authentication packages registry entries to establish creation/modification timelines. 5. Examine file system artifacts for unsigned or anomalous DLLs in system directories that could serve as authentication packages. 6. Correlate registry LastWrite timestamps with system boot events to identify persistence installation timing.', 'SELECT EventTime, Computer, EventData.ProcessName, EventData.Image, EventData.ImageLoaded, EventData.Signed, EventData.SignatureStatus FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'') WHERE System.EventID.Value = 7 AND EventData.Image =~ ''lsass.exe'' AND (EventData.Signed = ''false'' OR EventData.SignatureStatus != ''Valid'')', 'name: Windows.Detection.T1547.002.AuthenticationPackage
description: Detect LSA Authentication Package persistence via registry modifications and LSASS DLL loads
sources:
  - name: RegistryModifications
    query: |
      SELECT EventTime, Computer, EventData.ObjectName, EventData.ObjectValueName, EventData.NewValue, EventData.ProcessName, EventData.SubjectUserName FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ ''CurrentControlSet.*Lsa'' AND EventData.ObjectValueName =~ ''(?i)(Authentication|Security|Notification).*Packages''
  - name: LSASSDLLLoads
    query: |
      SELECT EventTime, Computer, EventData.ProcessName, EventData.Image, EventData.ImageLoaded, EventData.Signed, EventData.SignatureStatus, EventData.Company FROM parse_evtx(filename=''C:/Windows/System32/winevt/Logs/Security.evtx'') WHERE System.EventID.Value = 7 AND EventData.Image =~ ''lsass.exe''
  - name: LSARegistryKeys
    query: |
      SELECT Key.OSPath.Path as KeyPath, Data.value as AuthPackages, Key.ModTime FROM source(artifact=''Windows.Registry.NTUser'') WHERE KeyPath =~ ''HKEY_LOCAL_MACHINE.*CurrentControlSet.*Control.*Lsa'' AND Data.value_name =~ ''(?i)Authentication.*Packages''', '2026-06-10 12:41:37.243319');
